package com.coinflow;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(CoinFlowConfig.CONFIG_GROUP)
public interface CoinFlowConfig extends Config
{
	String CONFIG_GROUP = "coin-flow";

	// ── General Section ──────────────────────────────────────────────────

	@ConfigSection(
		name = "General",
		description = "General tracking settings",
		position = 0
	)
	String generalSection = "general";

	@ConfigItem(
		keyName = "trackSpent",
		name = "Track Spent",
		description = "Track supply costs and expenses, deducting them from profit (disable for gross tracking)",
		section = generalSection,
		position = 0
	)
	default boolean trackSpent()
	{
		return true;
	}

	// ── Display Section ──────────────────────────────────────────────────

	@ConfigSection(
		name = "Display",
		description = "Overlay, side panel, and gold drop display settings",
		position = 1
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show Overlay",
		description = "Toggle the on-screen profit overlay",
		section = displaySection,
		position = 0
	)
	default boolean showOverlay()
	{
		return true;
	}

	enum OverlayStyle
	{
		DETAILED("Detailed"),
		SINGLE_LINE("Single Line");

		private final String name;

		OverlayStyle(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigItem(
		keyName = "overlayStyle",
		name = "Overlay Style",
		description = "Detailed shows profit, spent, GP/hr, time and goal progress; Single Line shows only the GP/hr rate",
		section = displaySection,
		position = 1
	)
	default OverlayStyle overlayStyle()
	{
		return OverlayStyle.DETAILED;
	}

	@ConfigItem(
		keyName = "showOverlayBackground",
		name = "Overlay Background",
		description = "Draw the panel background behind the overlay (disable for text only)",
		section = displaySection,
		position = 2
	)
	default boolean showOverlayBackground()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showItemBreakdown",
		name = "Show Item Breakdown",
		description = "Show per-item breakdown in the side panel",
		section = displaySection,
		position = 3
	)
	default boolean showItemBreakdown()
	{
		return false;
	}

	@ConfigItem(
		keyName = "compactMode",
		name = "Compact Mode",
		description = "Display a streamlined, compact view in the side panel",
		section = displaySection,
		position = 4
	)
	default boolean compactMode()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showGoldDrops",
		name = "Show Gold Drops",
		description = "Display floating gold drops when gaining profit",
		section = displaySection,
		position = 5
	)
	default boolean showGoldDrops()
	{
		return false;
	}

	enum GoldDropPosition
	{
		TOP_RIGHT("Top Right (XP Drops)"),
		OVERHEAD("Overhead (Player)");

		private final String name;

		GoldDropPosition(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigItem(
		keyName = "goldDropPosition",
		name = "Drop Position",
		description = "Where to display floating gold drops on screen",
		section = displaySection,
		position = 6
	)
	default GoldDropPosition goldDropPosition()
	{
		return GoldDropPosition.TOP_RIGHT;
	}

	@ConfigItem(
		keyName = "goldDropMinThreshold",
		name = "Min Gold Drop (GP)",
		description = "Minimum GP value required to trigger an in-game gold drop (0 to show all)",
		section = displaySection,
		position = 7
	)
	@Range(min = 0)
	default int goldDropMinThreshold()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "sessionCardCollapsed",
		name = "Collapse Session Card",
		description = "Collapse session card in side panel",
		hidden = true
	)
	default boolean sessionCardCollapsed()
	{
		return false;
	}

	@ConfigItem(
		keyName = "goalCardCollapsed",
		name = "Collapse Goal Card",
		description = "Collapse goal progress card in side panel",
		hidden = true
	)
	default boolean goalCardCollapsed()
	{
		return false;
	}

	@ConfigItem(
		keyName = "itemsCardCollapsed",
		name = "Collapse Items Card",
		description = "Collapse item breakdown card in side panel",
		hidden = true
	)
	default boolean itemsCardCollapsed()
	{
		return false;
	}

	// ── Goal Section ─────────────────────────────────────────────────────

	@ConfigSection(
		name = "Goal",
		description = "Target GP goals and countdown settings",
		position = 2
	)
	String goalSection = "goal";

	@ConfigItem(
		keyName = "showGoalOverlay",
		name = "Show Goal in Overlay",
		description = "Display a mini progress bar and ETA in the overlay HUD",
		section = goalSection,
		position = 0
	)
	default boolean showGoalOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "goalAmount",
		name = "Target GP",
		description = "The target GP amount to work towards (e.g. 10m, 500k, 10000; blank to disable)",
		section = goalSection,
		position = 1
	)
	default String goalAmount()
	{
		return "";
	}

	@ConfigItem(
		keyName = "goalName",
		name = "Goal Label",
		description = "A custom label for your goal (e.g. Old School Bond)",
		section = goalSection,
		position = 2
	)
	default String goalName()
	{
		return "";
	}

	@ConfigItem(
		keyName = "notifyOnGoal",
		name = "Notify on Completion",
		description = "Send a notification when the target GP goal is reached",
		section = goalSection,
		position = 3
	)
	default boolean notifyOnGoal()
	{
		return true;
	}

	// ── Reporting Section ─────────────────────────────────────────────────

	@ConfigSection(
		name = "Reporting",
		description = "Reporting settings",
		position = 3,
		closedByDefault = true
	)
	String reportingSection = "reporting";

	@ConfigItem(
		keyName = "displaySummary",
		name = "Display Summary on Reset",
		description = "Display the session summary dialog when resetting an active session",
		section = reportingSection,
		position = 0
	)
	default boolean displaySummary()
	{
		return false;
	}

	// ── Advanced Section ─────────────────────────────────────────────────

	@ConfigSection(
		name = "Advanced",
		description = "Advanced tracking settings",
		position = 4,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "includeAfkTime",
		name = "Include AFK Time",
		description = "Include AFK and idle time in the GP/hr calculation instead of pausing while inactive",
		section = advancedSection,
		position = 0
	)
	default boolean includeAfkTime()
	{
		return false;
	}

	@ConfigItem(
		keyName = "idleTimeoutMinutes",
		name = "Idle Timeout (minutes)",
		description = "Minutes of player inactivity before pausing the GP/hr timer (when Include AFK Time is disabled)",
		section = advancedSection,
		position = 1
	)
	@Range(min = 1, max = 60)
	default int idleTimeoutMinutes()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "ignoredItems",
		name = "Ignored Items",
		description = "Comma-separated item names to exclude from tracking",
		section = advancedSection,
		position = 2
	)
	default String ignoredItems()
	{
		return "";
	}

	@ConfigItem(
		keyName = "trackWeaponCharges",
		name = "Track Weapon Charges",
		description = "Deduct runes, scales, and other resources consumed inside charged weapons (blowpipe, tridents, etc.) from profit",
		section = advancedSection,
		position = 3
	)
	default boolean trackWeaponCharges()
	{
		return true;
	}

	@ConfigItem(
		keyName = "untrackedSalesAsIncome",
		name = "Stock Sales as Income",
		description = "Count proceeds from selling untracked (banked or pre-session) items at shops or the GE as income instead of a net-zero asset conversion",
		section = advancedSection,
		position = 4
	)
	default boolean untrackedSalesAsIncome()
	{
		return false;
	}

	@ConfigItem(
		keyName = "countDropsAsSpent",
		name = "Count Drops as Spent",
		description = "Record items you Drop as a supply expense (Spent) instead of deducting them from gross profit. Picking the item back up reverses the expense. Requires Track Spent.",
		section = advancedSection,
		position = 5
	)
	default boolean countDropsAsSpent()
	{
		return false;
	}
}

package com.coinflow;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Iterator;
import java.util.concurrent.ConcurrentLinkedDeque;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

@Singleton
public class CoinFlowGoldDropOverlay extends Overlay
{
	private static final int MAX_DROPS = 10;
	static final long DURATION_MS = 1800;
	private static final Color GOLD_DROP_COLOR = new Color(0xFF, 0xD7, 0x00);

	private static final int[] XP_ORB_WIDGET_IDS = {
		InterfaceID.Orbs.XP_DROPS,
		InterfaceID.OrbsNomap.XP_DROPS,
		InterfaceID.OrbsOsm.XP_DROPS,
		InterfaceID.OrbsOsmNomap.XP_DROPS,
		InterfaceID.XpDrops.CONTAINER
	};

	private final Client client;
	private final ItemManager itemManager;
	private final CoinFlowConfig config;
	final ConcurrentLinkedDeque<GoldDrop> drops = new ConcurrentLinkedDeque<>();

	@Inject
	public CoinFlowGoldDropOverlay(CoinFlowPlugin plugin, Client client, ItemManager itemManager, CoinFlowConfig config)
	{
		super(plugin);
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_MED);
	}

	public void addDrop(String text, int itemId, int verticalOffset)
	{
		while (drops.size() >= MAX_DROPS)
		{
			drops.pollFirst();
		}
		drops.addLast(new GoldDrop(text, itemId, System.currentTimeMillis(), verticalOffset));
	}

	public void clear()
	{
		drops.clear();
	}

	Point getXpDropLocation()
	{
		for (int id : XP_ORB_WIDGET_IDS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				Point loc = widget.getCanvasLocation();
				if (loc != null && loc.getX() > 0 && loc.getY() > 0)
				{
					// Anchor to the right edge just to the left of the XP orb, starting below and floating upward
					return new Point(loc.getX() - 15, loc.getY() + 70);
				}
			}
		}

		return new Point(Math.max(100, client.getCanvasWidth() - 160), 160);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showGoldDrops() || drops.isEmpty() || client == null)
		{
			return null;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			drops.clear();
			return null;
		}

		long now = System.currentTimeMillis();
		boolean isTopRight = config.goldDropPosition() == CoinFlowConfig.GoldDropPosition.TOP_RIGHT;
		Point topRightOrigin = isTopRight ? getXpDropLocation() : null;

		LocalPoint loc = isTopRight ? null : localPlayer.getLocalLocation();
		if (!isTopRight && loc == null)
		{
			return null;
		}
		int zOffset = isTopRight ? 0 : localPlayer.getLogicalHeight() + 30;

		Font prevFont = graphics.getFont();
		if (isTopRight)
		{
			graphics.setFont(FontManager.getRunescapeBoldFont());
		}

		try
		{
			Iterator<GoldDrop> it = drops.iterator();

			while (it.hasNext())
			{
				GoldDrop drop = it.next();
				long elapsed = now - drop.spawnTime;
				if (elapsed >= DURATION_MS)
				{
					it.remove();
					continue;
				}

				float progress = (float) elapsed / DURATION_MS;
				float alpha = Math.max(0.0f, Math.min(1.0f, 1.0f - progress));

				Point drawLoc;
				if (isTopRight)
				{
					int floatY = (int) (progress * 55);
					// Floats UP towards the XP counter, matching real OSRS XP drops
					drawLoc = new Point(topRightOrigin.getX(), topRightOrigin.getY() - floatY + drop.verticalOffset);
				}
				else
				{
					int floatY = (int) (progress * 45);
					Point baseLoc = Perspective.getCanvasTextLocation(client, graphics, loc, drop.text, zOffset);
					if (baseLoc == null)
					{
						continue;
					}
					drawLoc = new Point(baseLoc.getX(), baseLoc.getY() - floatY - drop.verticalOffset);
				}

				Composite origComposite = graphics.getComposite();
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

				try
				{
					int iconId = drop.itemId > 0 ? drop.itemId : ItemID.COINS_10000;
					BufferedImage icon = itemManager != null ? itemManager.getImage(iconId) : null;
					if (icon == null && itemManager != null)
					{
						icon = itemManager.getImage(ItemID.COINS);
					}

					int textX = drawLoc.getX();
					if (isTopRight)
					{
						int textWidth = graphics.getFontMetrics().stringWidth(drop.text);
						textX = topRightOrigin.getX() - textWidth;
					}

					if (icon != null)
					{
						graphics.drawImage(icon, textX - 18, drawLoc.getY() - 13, 16, 16, null);
					}

					OverlayUtil.renderTextLocation(graphics, new Point(textX, drawLoc.getY()), drop.text, GOLD_DROP_COLOR);
				}
				finally
				{
					graphics.setComposite(origComposite);
				}
			}
		}
		finally
		{
			if (isTopRight)
			{
				graphics.setFont(prevFont);
			}
		}

		return null;
	}

	static class GoldDrop
	{
		final String text;
		final int itemId;
		final long spawnTime;
		final int verticalOffset;

		GoldDrop(String text, int itemId, long spawnTime, int verticalOffset)
		{
			this.text = text;
			this.itemId = itemId;
			this.spawnTime = spawnTime;
			this.verticalOffset = verticalOffset;
		}
	}
}

package com.coinflow;

import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.DocumentFilter;

/**
 * Real-time DocumentFilter and utility for ensuring user-facing text fields
 * across the Coin Flow plugin (both in the side panel and RuneLite config panel)
 * strictly reject special characters.
 */
public class CoinFlowInputFilter extends DocumentFilter
{
	public static final String DIGITS_ONLY = "[^0-9]";
	public static final String TARGET_GP = "[^0-9.,kKmMbB]";
	public static final String GOAL_NAME = "[^a-zA-Z0-9 '()/\\-]";
	public static final String IGNORED_ITEMS = "[^a-zA-Z0-9 ',()\\-]";

	private final String disallowedRegex;
	private final int maxLength;

	public CoinFlowInputFilter(String disallowedRegex, int maxLength)
	{
		this.disallowedRegex = disallowedRegex;
		this.maxLength = maxLength;
	}

	@Override
	public void insertString(FilterBypass fb, int offset, String string, AttributeSet attr) throws BadLocationException
	{
		if (string == null)
		{
			return;
		}
		String sanitized = string.replaceAll(disallowedRegex, "");
		if (sanitized.isEmpty())
		{
			return;
		}
		int currentLen = fb.getDocument().getLength();
		if (currentLen + sanitized.length() > maxLength)
		{
			int available = maxLength - currentLen;
			if (available <= 0)
			{
				return;
			}
			sanitized = sanitized.substring(0, available);
		}
		super.insertString(fb, offset, sanitized, attr);
	}

	@Override
	public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs) throws BadLocationException
	{
		if (text == null)
		{
			super.replace(fb, offset, length, null, attrs);
			return;
		}
		String sanitized = text.replaceAll(disallowedRegex, "");
		int currentLen = fb.getDocument().getLength();
		int newLen = currentLen - length + sanitized.length();
		if (newLen > maxLength)
		{
			int available = maxLength - (currentLen - length);
			if (available <= 0)
			{
				return;
			}
			sanitized = sanitized.substring(0, available);
		}
		super.replace(fb, offset, length, sanitized, attrs);
	}
}

package com.coinflow;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Duration;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

public class CoinFlowOverlay extends OverlayPanel
{
	private static final Color TITLE_COLOR = new Color(0xFF, 0xD7, 0x00); // Gold
	private static final Color PROFIT_COLOR = new Color(0x00, 0xFF, 0x80); // Green
	private static final Color LABEL_COLOR = Color.WHITE;
	private static final Color IDLE_COLOR = new Color(0xFF, 0xA5, 0x00);  // Orange
	private static final Color GOAL_COMPLETE_COLOR = new Color(24, 134, 52); // Rich forest green (#188634) with high contrast for white text
	private static final Color GOAL_IN_PROGRESS_COLOR = new Color(205, 110, 0); // Warm amber orange
	private static final Color LOSS_COLOR = new Color(0xE7, 0x4C, 0x3C);
	private static final Color PROGRESS_BAR_BG = new Color(0x28, 0x28, 0x28);

	private static final int MIN_PANEL_WIDTH = 140;
	private static final int PANEL_PADDING = 16;
	private static final int COLUMN_SPACING = 12;

	private final CoinFlowPlugin plugin;
	private final CoinFlowConfig config;

	@Inject
	public CoinFlowOverlay(CoinFlowPlugin plugin, CoinFlowConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
		panelComponent.setPreferredSize(new Dimension(MIN_PANEL_WIDTH, 0));
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", "Coin Flow overlay"));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		CoinFlowSession session = plugin.getSession();
		if (session == null)
		{
			return null;
		}

		boolean includeAfk = config.includeAfkTime();
		boolean isIdle = session.isIdle();

		// Use the standard color (not a copy) when the background is enabled so
		// OverlayPanel's preferred-color substitution (the global "Overlay Color"
		// setting) still applies; null keeps the panel fully transparent.
		panelComponent.setBackgroundColor(config.showOverlayBackground()
			? ComponentConstants.STANDARD_BACKGROUND_COLOR
			: null);

		boolean singleLine = config.overlayStyle() == CoinFlowConfig.OverlayStyle.SINGLE_LINE;
		// A resized overlay's saved size is ignored in single-line mode, so hide the resize handles.
		setResizable(!singleLine);
		if (singleLine)
		{
			return renderSingleLine(graphics, session, isIdle, includeAfk);
		}

		FontMetrics fontMetrics = graphics.getFontMetrics();
		int maxLineWidth = MIN_PANEL_WIDTH;

		// ── Title ────────────────────────────────────────────────────
		String titleText = formatTitle(isIdle);
		maxLineWidth = Math.max(maxLineWidth, fontMetrics.stringWidth(titleText));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(titleText)
			.color(isIdle ? IDLE_COLOR : TITLE_COLOR)
			.build());

		// ── Profit & Supplies (Dynamic Unified Display) ──────────────
		boolean trackSpent = config.trackSpent();
		long totalExpenses = trackSpent ? session.getTotalExpenses() : 0L;
		long totalProfit = trackSpent ? session.getTotalProfit() : session.getGrossProfit();
		String profitLabel = trackSpent ? "Net Profit:" : "Profit:";
		String totalProfitRight = (totalProfit < 0 ? "-" : "") + formatGp(Math.abs(totalProfit)) + " gp";
		Color profitColor = totalProfit < 0 ? LOSS_COLOR : PROFIT_COLOR;

		maxLineWidth = Math.max(maxLineWidth, fontMetrics.stringWidth(profitLabel) + fontMetrics.stringWidth(totalProfitRight) + COLUMN_SPACING);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(profitLabel)
			.leftColor(LABEL_COLOR)
			.right(totalProfitRight)
			.rightColor(profitColor)
			.build());

		if (trackSpent)
		{
			String spentLeft = "Spent:";
			String spentRight = (totalExpenses > 0 ? "-" : "") + formatGp(totalExpenses) + " gp";
			Color spentColor = totalExpenses > 0 ? LOSS_COLOR : LABEL_COLOR;
			maxLineWidth = Math.max(maxLineWidth, fontMetrics.stringWidth(spentLeft) + fontMetrics.stringWidth(spentRight) + COLUMN_SPACING);
			panelComponent.getChildren().add(LineComponent.builder()
				.left(spentLeft)
				.leftColor(LABEL_COLOR)
				.right(spentRight)
				.rightColor(spentColor)
				.build());
		}

		// ── GP/Hour ──────────────────────────────────────────────────
		long gpPerHour = trackSpent ? session.getGpPerHour(includeAfk) : session.getGrossGpPerHour(includeAfk);
		String gpHrLeft = "GP/Hour:";
		String gpHrRight = (gpPerHour < 0 ? "-" : "") + formatGp(Math.abs(gpPerHour)) + " gp/hr";
		Color gpHrColor = isIdle ? IDLE_COLOR : (gpPerHour < 0 ? LOSS_COLOR : PROFIT_COLOR);
		maxLineWidth = Math.max(maxLineWidth, fontMetrics.stringWidth(gpHrLeft) + fontMetrics.stringWidth(gpHrRight) + COLUMN_SPACING);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(gpHrLeft)
			.leftColor(LABEL_COLOR)
			.right(gpHrRight)
			.rightColor(gpHrColor)
			.build());

		// ── Active / Session Time ─────────────────────────────────────
		Duration displayTime = session.getTime(includeAfk);
		String timeLeft = "Time:";
		String timeRight = formatTimeRight(displayTime, isIdle, includeAfk);
		maxLineWidth = Math.max(maxLineWidth, fontMetrics.stringWidth(timeLeft) + fontMetrics.stringWidth(timeRight) + COLUMN_SPACING);
		panelComponent.getChildren().add(LineComponent.builder()
			.left(timeLeft)
			.leftColor(LABEL_COLOR)
			.right(timeRight)
			.rightColor(isIdle ? IDLE_COLOR : LABEL_COLOR)
			.build());

		// ── Goal Progress Bar ─────────────────────────────────────────
		ProgressBarComponent progressBar = null;
		long goalAmount = CoinFlowSession.parseGoalAmount(config.goalAmount());
		if (config.showGoalOverlay() && goalAmount > 0)
		{
			double progress = session.getGoalProgress(goalAmount, trackSpent);
			boolean isGoalComplete = progress >= 1.0;
			long etaSeconds = session.getGoalEtaSeconds(goalAmount, includeAfk, trackSpent);
			String etaStr = CoinFlowSession.formatGoalEta(etaSeconds);

			String goalName = CoinFlowSession.cleanGoalName(config.goalName());
			String goalLabel = goalName.isEmpty() ? "Goal" : goalName;
			String percentStr = String.format("%.1f%%", progress * 100);

			String barCenterText = isGoalComplete
				? "Goal Reached! (100%)"
				: (goalLabel + " " + percentStr + " - " + etaStr);

			maxLineWidth = Math.max(maxLineWidth, fontMetrics.stringWidth(barCenterText) + 8);

			progressBar = new ProgressBarComponent();
			progressBar.setMinimum(0);
			progressBar.setMaximum(goalAmount);
			progressBar.setValue(Math.min((double) goalAmount, Math.max(0.0, (double) totalProfit)));
			progressBar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
			progressBar.setCenterLabel(barCenterText);
			progressBar.setForegroundColor(isGoalComplete ? GOAL_COMPLETE_COLOR : GOAL_IN_PROGRESS_COLOR);
			progressBar.setBackgroundColor(PROGRESS_BAR_BG);
			progressBar.setFontColor(Color.WHITE);

			panelComponent.getChildren().add(progressBar);
		}

		// Set progress bar width to match the full panel width
		if (progressBar != null)
		{
			progressBar.setPreferredSize(new Dimension(maxLineWidth, 16));
		}

		// Dynamically size panel width to comfortably fit the widest line without awkward wrapping
		panelComponent.setPreferredSize(new Dimension(maxLineWidth + PANEL_PADDING, 0));

		return super.render(graphics);
	}

	/**
	 * Renders the compact single-line "GP/hr" display.
	 *
	 * Renders {@link #panelComponent} directly instead of via {@code super.render()} so a
	 * saved overlay resize ({@code getPreferredSize()}) cannot force a stale width that
	 * would stretch the background or wrap the line. Mirrors OverlayPanel's
	 * preferred-color swap so the global "Overlay Color" setting still applies.
	 */
	private Dimension renderSingleLine(Graphics2D graphics, CoinFlowSession session, boolean isIdle, boolean includeAfk)
	{
		long gpPerHour = config.trackSpent() ? session.getGpPerHour(includeAfk) : session.getGrossGpPerHour(includeAfk);
		String text = formatCompactGpPerHour(gpPerHour);
		Color color = isIdle ? IDLE_COLOR : (gpPerHour < 0 ? LOSS_COLOR : PROFIT_COLOR);

		FontMetrics fontMetrics = graphics.getFontMetrics();
		panelComponent.setPreferredSize(new Dimension(fontMetrics.stringWidth(text) + PANEL_PADDING, 0));
		panelComponent.getChildren().add(LineComponent.builder()
			.left(text)
			.leftColor(color)
			.build());

		Color background = panelComponent.getBackgroundColor();
		if (background != null && getPreferredColor() != null)
		{
			panelComponent.setBackgroundColor(getPreferredColor());
		}

		try
		{
			return panelComponent.render(graphics);
		}
		finally
		{
			if (isClearChildren())
			{
				panelComponent.getChildren().clear();
			}
			panelComponent.setBackgroundColor(background);
		}
	}

	/**
	 * Formats the single-line overlay text, e.g. "721 gp/hr" or "-50 gp/hr".
	 */
	static String formatCompactGpPerHour(long gpPerHour)
	{
		return (gpPerHour < 0 ? "-" : "") + formatGp(Math.abs(gpPerHour)) + " gp/hr";
	}

	/**
	 * Formats a GP value with abbreviations (e.g., 1.2M, 456K).
	 */
	private static String formatGp(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}

	/**
	 * Formats a duration as compact digital "mm:ss" or "h:mm:ss" to prevent wrapping.
	 */
	private static String formatDuration(Duration duration)
	{
		long totalSeconds = Math.max(0, duration.getSeconds());
		long hours = totalSeconds / 3600;
		long minutes = (totalSeconds % 3600) / 60;
		long seconds = totalSeconds % 60;

		if (hours > 0)
		{
			return String.format("%d:%02d:%02d", hours, minutes, seconds);
		}
		return String.format("%02d:%02d", minutes, seconds);
	}

	/**
	 * Formats the overlay title text based on idle state.
	 */
	static String formatTitle(boolean isIdle)
	{
		return isIdle ? "Coin Flow (idle)" : "Coin Flow";
	}

	/**
	 * Formats the right-side Time text in the overlay based on idle and includeAfk configuration.
	 */
	static String formatTimeRight(Duration displayTime, boolean isIdle, boolean includeAfk)
	{
		return formatDuration(displayTime) + (isIdle ? (includeAfk ? " (idle)" : " (paused)") : "");
	}
}

