	static int parseSeedQtyInMessage(String msg)
	{
		Matcher m = Pattern.compile("(\\d+)\\s*x", Pattern.CASE_INSENSITIVE).matcher(msg);
		if (m.find())
		{
			try
			{
				return Integer.parseInt(m.group(1));
			}
			catch (NumberFormatException ignored) {}
		}
		return 1;
	}

