	public CoinFlowSession withLastActivityTime(Instant lastActivityTime)
	{
		return new CoinFlowSession(
			this.trackedItems,
			this.trackedExpenses,
			this.grossProfit,
			this.totalExpenses,
			this.sessionStartTime,
			this.activeTime,
			this.totalInGameTime,
			lastActivityTime,
			this.lastTickTime,
			this.idle
		);
