	 */
	public static boolean isMasterScrollBookVarbit(int varbitId)
	{
		if (varbitId == VarbitID.BOOKOFSCROLLS_WATSON_LOWBITS || varbitId == VarbitID.BOOKOFSCROLLS_WATSON_HIGHBITS)
		{
			return true;
		}
		for (int v : SCROLL_BOOK_VARBITS)
		{
