	/** varbit id -> last observed charge count */
	private final Map<Integer, Integer> lastCharges = new HashMap<>();

	/** fractional resource remainder per (source, resource item) */
	private final Map<String, Double> resourceRemainders = new HashMap<>();

	/** resource item id -> whole units consumed since last drain */
	private final Map<Integer, Integer> pendingResources = new HashMap<>();

	/** varbit id -> attack-triggered charges already expensed, for varbit delta dedup */
	private final Map<Integer, AttackDedupe> recentAttackCharges = new HashMap<>();

	private int lastLoadedDartItemId = -1;
	private double dartRecoveryRate;

	/**
	 * Records an attack graphic played on the local player while {@code weaponName} is equipped.
	 */
	void onAttackGraphic(int graphicId, String weaponName, int tick)
	{
		AttackProfile profile = findProfile(weaponName);
		if (profile == null || !profile.graphics.contains(graphicId))
		{
			return;
		}
		consumeAttack(profile, "graphic " + graphicId, tick);
	}

	/**
	 * Records an attack animation played on the local player while {@code weaponName} is equipped.
	 */
	void onAttackAnimation(int animationId, String weaponName, int tick)
	{
		AttackProfile profile = findProfile(weaponName);
		if (profile == null || !profile.animations.contains(animationId))
		{
			return;
		}
		consumeAttack(profile, "animation " + animationId, tick);
	}

	/**
	 * Records a charge varbit update. {@code trackingAllowed} should be false while
	 * inventory tracking is suppressed or a rebaseline is pending (e.g. uncharge at a
	 * bank); in that case the new value is baselined without recording expense.
	 * Charges already expensed via attack triggers within the last few ticks are
	 * deducted from the delta to avoid double counting.
	 */
	void onVarbitChanged(int varbitId, int newValue, boolean trackingAllowed, int tick)
	{
		WeaponConfig config = CONFIGS.get(varbitId);
		if (config == null)
		{
			return;
		}

		Integer previous = lastCharges.put(varbitId, newValue);
		if (previous == null || previous == newValue)
		{
			return;
		}

		log.debug("Weapon charge varbit {} ({}): {} -> {} (trackingAllowed={})",
			varbitId, config.name, previous, newValue, trackingAllowed);

		if (!trackingAllowed)
		{
			return;
		}

		int consumed = previous - newValue;
		if (consumed <= 0)
		{
			return;
		}

		AttackDedupe dedupe = recentAttackCharges.get(varbitId);
		if (dedupe != null)
		{
			if (tick - dedupe.lastTick <= 2)
			{
				int alreadyCounted = Math.min(consumed, dedupe.count);
				dedupe.count -= alreadyCounted;
				consumed -= alreadyCounted;
			}
			else
			{
				recentAttackCharges.remove(varbitId);
			}
			if (dedupe.count <= 0)
			{
				recentAttackCharges.remove(varbitId);
			}
		}
		if (consumed <= 0)
		{
			return;
		}

		for (ChargeCost cost : config.costs)
		{
			accumulate("varbit:" + varbitId, cost.itemId, consumed * (double) cost.numerator / cost.denominator);
		}
	}

	/** Returns and clears the whole resource units consumed since the last drain. */
	Map<Integer, Integer> drain()
	{
		if (pendingResources.isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> result = new HashMap<>(pendingResources);
		pendingResources.clear();
		return result;
	}

	/**
	 * Records the dart type loaded into a blowpipe, parsed from the source name of a
	 * "Use <dart> -> Toxic blowpipe" menu click.
	 */
	void recordUseSource(String itemName)
	{
		if (itemName == null)
		{
			return;
		}
		String lower = itemName.trim().toLowerCase(Locale.ROOT);
		if (lower.startsWith("use "))
		{
			lower = lower.substring(4).trim();
		}
		Integer dartId = DART_ITEM_IDS.get(lower);
		if (dartId != null)
		{
			lastLoadedDartItemId = dartId;
		}
	}

	/** Fraction of consumed darts recovered by the equipped Ava's device (0 when none). */
	void setDartRecoveryRate(double dartRecoveryRate)
	{
		this.dartRecoveryRate = Math.max(0.0, Math.min(1.0, dartRecoveryRate));
	}

	/**
	 * Clears the remembered blowpipe dart type (called when the weapon is unloaded).
	 * Darts persist inside the blowpipe across banking, rebaselines and logout, so
	 * {@link #reset()} intentionally does NOT clear this state.
	 */
	void clearLoadedDarts()
	{
		lastLoadedDartItemId = -1;
	}

	/** Clears all baselines and pending spend (session reset / logout / full rebaseline). */
	void reset()
	{
		lastCharges.clear();
		resourceRemainders.clear();
		pendingResources.clear();
		recentAttackCharges.clear();
		// lastLoadedDartItemId survives: the blowpipe's darts are still loaded
	}

	static boolean isTrackedVarbit(int varbitId)
	{
		return CONFIGS.containsKey(varbitId);
	}

	static Set<Integer> trackedVarbitIds()
	{
		return Collections.unmodifiableSet(CONFIGS.keySet());
	}

	private AttackProfile findProfile(String weaponName)
	{
		if (weaponName == null)
		{
			return null;
		}
		String lower = weaponName.toLowerCase(Locale.ROOT);
		for (AttackProfile profile : ATTACK_PROFILES)
		{
			if (lower.contains(profile.weaponNameMatch))
			{
				return profile;
			}
		}
		return null;
	}

	private void consumeAttack(AttackProfile profile, String trigger, int tick)
	{
		log.debug("Charged weapon attack via {} ({}): {}", trigger, profile.weaponNameMatch,
			profile.consumesDarts ? "scales + darts" : profile.costsPerAttack.size() + " resource(s)");
		for (ChargeCost cost : profile.costsPerAttack)
		{
			accumulate("attack:" + profile.weaponNameMatch, cost.itemId,
				(double) cost.numerator / cost.denominator);
		}
		if (profile.consumesDarts && lastLoadedDartItemId > 0)
		{
			accumulate("attack:" + profile.weaponNameMatch, lastLoadedDartItemId, 1.0 - dartRecoveryRate);
		}
		for (int varbitId : profile.dedupeVarbitIds)
		{
			AttackDedupe dedupe = recentAttackCharges.computeIfAbsent(varbitId, k -> new AttackDedupe());
			dedupe.count++;
			dedupe.lastTick = tick;
		}
	}

	private void accumulate(String source, int itemId, double units)
	{
		String key = source + ":" + itemId;
		double total = resourceRemainders.getOrDefault(key, 0.0) + units;
		// Epsilon absorbs floating point error at whole-unit boundaries (e.g. 1.0 - 0.8)
		int whole = (int) (total + 1e-9);
		resourceRemainders.put(key, total - whole);
		if (whole > 0)
		{
			pendingResources.merge(itemId, whole, Integer::sum);
		}
	}
}

package com.coinflow.reconciliation;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Handles charged jewelry, tools, and degradable equipment
 * (e.g. Amulet of glory(5) -> Amulet of glory(4), Ring of dueling(8) -> (7),
 * Amulet of glory(1) -> uncharged Amulet of glory, Barrows 100 -> 75 -> 50 -> 25 -> 0).
 * Reconciles the degraded item in rawGains against the higher-charge item in rawLosses,
 * preventing charged jewelry usage from generating false profit loot.
 */
@Slf4j
public class ChargeDegradationHandler implements ReconciliationHandler
{
	// Matches "Amulet of glory(5)", "Ring of dueling (8)", "Amulet of glory (t5)"
	private static final Pattern CHARGED_PATTERN = Pattern.compile("^(.*?)\\s*\\(([a-zA-Z]*)(\\d+)\\)$");

	// Matches Barrows degrade stages: "Dharok's helm 100" -> 75 -> 50 -> 25 -> 0
	private static final Pattern BARROWS_PATTERN = Pattern.compile("^(.*?)\\s+(100|75|50|25|0)$");

	private static final class ChargeInfo
	{
		final String baseName;
		final String tag;
		final int charges;

		ChargeInfo(String baseName, String tag, int charges)
		{
			this.baseName = baseName.trim();
			this.tag = tag != null ? tag.trim() : "";
			this.charges = charges;
		}
	}

	private static ChargeInfo parseCharge(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return null;
		}

		Matcher m = CHARGED_PATTERN.matcher(itemName);
		if (m.matches())
		{
			try
			{
				int charges = Integer.parseInt(m.group(3));
				return new ChargeInfo(m.group(1), m.group(2), charges);
			}
			catch (NumberFormatException ignored)
			{
			}
		}

		return null;
	}

	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();

		if (!rawLosses.isEmpty() && !rawGains.isEmpty())
		{
			List<Integer> lostKeys = new ArrayList<>(rawLosses.keySet());
			for (int lostId : lostKeys)
			{
				Integer lostQtyBoxed = rawLosses.get(lostId);
				if (lostQtyBoxed == null || lostQtyBoxed <= 0)
				{
					continue;
				}
				int lostQty = lostQtyBoxed;

				int canonicalLostId = itemManager != null ? itemManager.canonicalize(lostId) : lostId;
				if (context.isDropIntent(canonicalLostId))
				{
					// Dropped, not transformed: leave for the own-drop path
					continue;
				}
				String lostName = context.getItemName(canonicalLostId);

				// Prefer a single-step usage transition (e.g. (3) -> (2)) over a
				// broader recharge/repair match, so a same-base loot pickup in the
				// same tick (e.g. a dropped Ring of dueling(8)) is not paired away.
				Integer gainedMatchId = null;
				Integer broadMatchId = null;
				for (int gainedId : rawGains.keySet())
				{
					int canonicalGainedId = itemManager != null ? itemManager.canonicalize(gainedId) : gainedId;
					String gainedName = context.getItemName(canonicalGainedId);

					if (isUsageStepPair(lostName, gainedName)
						|| isLightSourcePair(canonicalLostId, canonicalGainedId, lostName, gainedName))
					{
						gainedMatchId = gainedId;
						break;
					}
					if (broadMatchId == null && isChargeDegradationPair(lostName, gainedName))
					{
						broadMatchId = gainedId;
					}
				}
				if (gainedMatchId == null)
				{
					gainedMatchId = broadMatchId;
				}

				if (gainedMatchId != null)
				{
					int gainedQty = rawGains.get(gainedMatchId);
					int matched = Math.min(lostQty, gainedQty);

					if (gainedQty <= matched)
					{
						rawGains.remove(gainedMatchId);
					}
					else
					{
						rawGains.put(gainedMatchId, gainedQty - matched);
					}

					if (lostQty <= matched)
					{
						rawLosses.remove(lostId);
					}
					else
					{
						rawLosses.put(lostId, lostQty - matched);
					}

					log.debug("Reconciled degradation/transition: {} -> {} (x{})", lostName, context.getItemName(gainedMatchId), matched);
				}
			}
		}

		// Suppress any lingering partially degraded items or lit light sources in rawGains (e.g. Slayer ring (2))
		// Partially degraded items cannot be obtained as drops or loot and indicate owned items
		// degrading across split ticks, teleport scene transitions, or unequipped after use.
		if (!rawGains.isEmpty())
		{
			List<Integer> gainedKeys = new ArrayList<>(rawGains.keySet());
			for (int gainedId : gainedKeys)
			{
				int canonicalGainedId = itemManager != null ? itemManager.canonicalize(gainedId) : gainedId;
				String gainedName = context.getItemName(canonicalGainedId);
				if (isPartiallyDegraded(gainedName) || isLitLightSource(canonicalGainedId, gainedName))
				{
					rawGains.remove(gainedId);
					log.debug("Suppressed partially degraded or lit item from profit gains: {}", gainedName);
				}
			}
		}
	}

	/**
	 * Checks if lostName transitioned into gainedName via a charge or degrade-state
	 * change on the same item: degradation (Slayer ring (3) -> (2)), depletion
	 * ((1) -> uncharged), recharge ((2) -> (4), base -> (4)), or Barrows repair /
	 * first-use ("X 50" -> "X", "X" -> "X 100").
	 */
	public static boolean isChargeDegradationPair(String lostName, String gainedName)
	{
		if (lostName == null || gainedName == null)
		{
			return false;
		}

		// 1. Parenthesized charges: same item at a different charge count —
		//    degrade steps, multi-charge drains, or fountain/altar recharges.
		ChargeInfo lostCharge = parseCharge(lostName);
		ChargeInfo gainedCharge = parseCharge(gainedName);
		if (lostCharge != null && gainedCharge != null)
		{
			return gainedCharge.baseName.equalsIgnoreCase(lostCharge.baseName)
				&& gainedCharge.tag.equalsIgnoreCase(lostCharge.tag)
				&& gainedCharge.charges != lostCharge.charges;
		}

		// 2. Charged <-> uncharged base name: (1) depleting to uncharged, or an
		//    uncharged item recharged back up (e.g. glory -> glory(4)).
		if (lostCharge != null && lostCharge.charges == 1 && matchesUnchargedBase(gainedName, lostCharge))
		{
			return true;
		}
		if (gainedCharge != null && matchesUnchargedBase(lostName, gainedCharge))
		{
			return true;
		}

		// 3. Barrows degrade states: same base item moving between any stages
		//    (100 -> 75 -> 50 -> 25 -> 0), to the repaired bare name
		//    ("X 50" -> "X"), or from it on first use ("X" -> "X 100"). The
		//    bare-name direction is limited to Barrows brothers' gear, since the
		//    stage pattern alone matches any name ending in those numbers.
		Matcher barrowsLost = BARROWS_PATTERN.matcher(lostName);
		Matcher barrowsGained = BARROWS_PATTERN.matcher(gainedName);
		boolean lostStaged = barrowsLost.matches();
		boolean gainedStaged = barrowsGained.matches();
		if (lostStaged || gainedStaged)
		{
			String lostBase = lostStaged ? barrowsLost.group(1).trim() : lostName.trim();
			String gainedBase = gainedStaged ? barrowsGained.group(1).trim() : gainedName.trim();
			return lostBase.equalsIgnoreCase(gainedBase)
				&& (lostStaged && gainedStaged || isBarrowsBrotherItem(lostBase));
		}

		return false;
	}

	/**
	 * Single-step usage transitions only: one charge drained ((3) -> (2)),
	 * (1) -> uncharged, or one Barrows stage down (100 -> 75). These are the
	 * unambiguous per-tick transitions and take priority over broader
	 * recharge/repair matches.
	 */
	static boolean isUsageStepPair(String lostName, String gainedName)
	{
		if (lostName == null || gainedName == null)
		{
			return false;
		}

		ChargeInfo lostCharge = parseCharge(lostName);
		ChargeInfo gainedCharge = parseCharge(gainedName);
		if (lostCharge != null && gainedCharge != null)
		{
			return gainedCharge.baseName.equalsIgnoreCase(lostCharge.baseName)
				&& gainedCharge.tag.equalsIgnoreCase(lostCharge.tag)
				&& gainedCharge.charges == lostCharge.charges - 1;
		}
		if (lostCharge != null && lostCharge.charges == 1 && matchesUnchargedBase(gainedName, lostCharge))
		{
			return true;
		}

		Matcher barrowsLost = BARROWS_PATTERN.matcher(lostName);
		Matcher barrowsGained = BARROWS_PATTERN.matcher(gainedName);
		if (barrowsLost.matches() && barrowsGained.matches())
		{
			return barrowsLost.group(1).trim().equalsIgnoreCase(barrowsGained.group(1).trim())
				&& barrowsGained.group(2).equals(nextBarrowsStage(barrowsLost.group(2)));
		}
		return false;
	}

	private static String nextBarrowsStage(String stage)
	{
		switch (stage)
		{
			case "100": return "75";
			case "75": return "50";
			case "50": return "25";
			case "25": return "0";
			default: return null;
		}
	}

	private static boolean isBarrowsBrotherItem(String baseName)
	{
		String lower = baseName.toLowerCase(java.util.Locale.ROOT);
		return lower.startsWith("ahrim's ") || lower.startsWith("dharok's ")
			|| lower.startsWith("guthan's ") || lower.startsWith("karil's ")
			|| lower.startsWith("torag's ") || lower.startsWith("verac's ");
	}

	private static boolean matchesUnchargedBase(String bareName, ChargeInfo charged)
	{
		String expectedUncharged = charged.tag.isEmpty()
			? charged.baseName
			: charged.baseName + " (" + charged.tag + ")";
		return bareName.equalsIgnoreCase(expectedUncharged) || bareName.equalsIgnoreCase(charged.baseName);
	}

	/**
	 * Checks if an item is a partially degraded variant that cannot be dropped as loot
	 * or produced from crafting (e.g. Slayer ring (2), Ring of dueling(7), Barrows 75/50/25/0).
	 */
	public static boolean isPartiallyDegraded(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}

		// 1. Barrows degraded stages (75, 50, 25, 0 are degraded; 100 is pristine)
		Matcher barrowsMatcher = BARROWS_PATTERN.matcher(itemName);
		if (barrowsMatcher.matches())
		{
			String stage = barrowsMatcher.group(2);
			return !"100".equals(stage);
		}

		// 2. Parenthesized charges
		ChargeInfo charge = parseCharge(itemName);
		if (charge == null)
		{
			return false;
		}

		String lowerBase = charge.baseName.toLowerCase(java.util.Locale.ROOT);
		int charges = charge.charges;

		if (lowerBase.contains("slayer ring"))
		{
			return charges < 8;
		}
		if (lowerBase.contains("ring of dueling") || lowerBase.contains("games necklace") || lowerBase.contains("pharaoh's sceptre"))
		{
			return charges < 8;
		}
		if (lowerBase.contains("glory") || lowerBase.contains("combat bracelet") || lowerBase.contains("skills necklace"))
		{
			return charges < 6;
		}
		if (lowerBase.contains("necklace of passage") || lowerBase.contains("burning amulet")
			|| lowerBase.contains("digsite pendant") || lowerBase.contains("ring of wealth")
			|| lowerBase.contains("abyssal bracelet"))
		{
			return charges < 5;
		}
		if (lowerBase.contains("dodgy necklace"))
		{
			return charges < 10;
		}
		if (lowerBase.contains("binding necklace"))
		{
			return charges < 16;
		}

		return false;
	}

	public static boolean isLightSourcePair(int lostId, int gainedId, String lostName, String gainedName)
	{
		if ((lostId == ItemID.BULLSEYE_LANTERN_LIT && gainedId == ItemID.BULLSEYE_LANTERN_UNLIT)
			|| (lostId == ItemID.BULLSEYE_LANTERN_UNLIT && gainedId == ItemID.BULLSEYE_LANTERN_LIT)
			|| (lostId == ItemID.BULLSEYE_LANTERN_LIT_LUNAR_QUEST && gainedId == ItemID.BULLSEYE_LANTERN_UNLIT_LUNAR_QUEST)
			|| (lostId == ItemID.BULLSEYE_LANTERN_UNLIT_LUNAR_QUEST && gainedId == ItemID.BULLSEYE_LANTERN_LIT_LUNAR_QUEST)
			|| (lostId == ItemID.OIL_LANTERN_LIT && gainedId == ItemID.OIL_LANTERN_UNLIT)
			|| (lostId == ItemID.OIL_LANTERN_UNLIT && gainedId == ItemID.OIL_LANTERN_LIT)
			|| (lostId == ItemID.CANDLE_LANTERN_LIT && gainedId == ItemID.CANDLE_LANTERN_UNLIT)
			|| (lostId == ItemID.CANDLE_LANTERN_UNLIT && gainedId == ItemID.CANDLE_LANTERN_LIT)
			|| (lostId == ItemID.CANDLE_LANTERN_BLACK_LIT && gainedId == ItemID.CANDLE_LANTERN_BLACK_UNLIT)
			|| (lostId == ItemID.CANDLE_LANTERN_BLACK_UNLIT && gainedId == ItemID.CANDLE_LANTERN_BLACK_LIT)
			|| (lostId == ItemID.OIL_LAMP_LIT && gainedId == ItemID.OIL_LAMP_UNLIT)
			|| (lostId == ItemID.OIL_LAMP_UNLIT && gainedId == ItemID.OIL_LAMP_LIT)
			|| (lostId == ItemID.TOG_SAPPHIRE_LANTERN_LIT && gainedId == ItemID.TOG_SAPPHIRE_LANTERN_UNLIT)
			|| (lostId == ItemID.TOG_SAPPHIRE_LANTERN_UNLIT && gainedId == ItemID.TOG_SAPPHIRE_LANTERN_LIT)
			|| (lostId == ItemID.CAVE_GOBLIN_MINING_HELMET_LIT && gainedId == ItemID.CAVE_GOBLIN_MINING_HELMET_UNLIT)
			|| (lostId == ItemID.CAVE_GOBLIN_MINING_HELMET_UNLIT && gainedId == ItemID.CAVE_GOBLIN_MINING_HELMET_LIT)
			|| (lostId == ItemID.LIT_CANDLE && gainedId == ItemID.UNLIT_CANDLE)
			|| (lostId == ItemID.UNLIT_CANDLE && gainedId == ItemID.LIT_CANDLE)
			|| (lostId == ItemID.LIT_BLACK_CANDLE && gainedId == ItemID.UNLIT_BLACK_CANDLE)
			|| (lostId == ItemID.UNLIT_BLACK_CANDLE && gainedId == ItemID.LIT_BLACK_CANDLE)
			|| (lostId == ItemID.TORCH_LIT && gainedId == ItemID.TORCH_UNLIT)
			|| (lostId == ItemID.TORCH_UNLIT && gainedId == ItemID.TORCH_LIT))
		{
			return true;
		}

		if (lostName != null && gainedName != null)
		{
			String l = lostName.toLowerCase(java.util.Locale.ROOT);
			String g = gainedName.toLowerCase(java.util.Locale.ROOT);
			String lBase = l.replace(" (lit)", "").replace(" lit", "").replace(" (unlit)", "").replace(" unlit", "").trim();
			String gBase = g.replace(" (lit)", "").replace(" lit", "").replace(" (unlit)", "").replace(" unlit", "").trim();
			if (!lBase.isEmpty() && lBase.equals(gBase))
			{
				boolean lIsLit = l.contains("lit");
				boolean gIsLit = g.contains("lit");
				if (lIsLit || gIsLit)
				{
					return true;
				}
			}
		}

		return false;
	}

	public static boolean isLitLightSource(int id, String name)
	{
		if (id == ItemID.BULLSEYE_LANTERN_LIT
			|| id == ItemID.BULLSEYE_LANTERN_LIT_LUNAR_QUEST
			|| id == ItemID.OIL_LANTERN_LIT
			|| id == ItemID.CANDLE_LANTERN_LIT
			|| id == ItemID.CANDLE_LANTERN_BLACK_LIT
			|| id == ItemID.OIL_LAMP_LIT
			|| id == ItemID.TOG_SAPPHIRE_LANTERN_LIT
			|| id == ItemID.CAVE_GOBLIN_MINING_HELMET_LIT
			|| id == ItemID.LIT_CANDLE
			|| id == ItemID.LIT_BLACK_CANDLE
			|| id == ItemID.TORCH_LIT)
		{
			return true;
		}
		if (name != null)
		{
			String lower = name.toLowerCase(java.util.Locale.ROOT);
			return (lower.contains("lantern") || lower.contains("candle") || lower.contains("torch") || lower.contains("lamp") || lower.contains("helmet"))
				&& (lower.contains("(lit)") || lower.startsWith("lit ") || lower.endsWith(" (lit)"));
		}
		return false;
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowSession;
import com.coinflow.ConsumableRegistry;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Final step in reconciliation: processes remaining lost items.
 * Consumable supplies (food, potions, runes, ammo, teleports) are recorded as supply expenses.
 * Non-consumable items dropped from inventory (coal, ore, logs) are recorded as dropped item deductions
 * bounded by prior session gains.
 */
@Slf4j
public class ConsumablesAndDropsHandler implements ReconciliationHandler
{
	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();
		CoinFlowSession session = context.getSession();
		Map<Integer, Integer> recentlyDroppedItems = context.getRecentlyDroppedItems();

		netCashExchange(context.getRawGains(), rawLosses);

		if (rawLosses.isEmpty())
		{
			return;
		}

		for (Map.Entry<Integer, Integer> entry : rawLosses.entrySet())
		{
			int lostId = entry.getKey();
			int quantity = entry.getValue();
			int itemId = itemManager.canonicalize(lostId);
			String itemName = context.getItemName(itemId);

			if (context.isIgnored(itemName))
			{
				continue;
			}

			// Opt-in: a confirmed "Drop" click is charged as a supply expense at
			// market price. Only click-confirmed drops qualify so unexplained
			// losses (quest hand-ins, Destroy, death) keep the legacy path.
			if (context.isDropsAsSpent() && context.isDropIntent(itemId))
			{
				long price = priceOf(itemId, itemManager);
				context.addDropExpense(itemId, new CoinFlowSession.TrackedItem(itemId, itemName, quantity, price));
				context.getRecentlyExpensedDrops().merge(itemId, quantity, Integer::sum);
				retireSessionGain(context, session, itemId, quantity);

				log.debug("Dropped item expensed: {} x{} @ {} gp = {} gp",
					itemName, quantity, price, (long) quantity * price);
				continue;
			}

			// Cash payments: coins/platinum leaving with no specialist claim is
			// money spent — fees, fares, repairs, coffers, services. Expense at
			// face value; a drop-intent coin loss keeps the own-drop path, and
			// cash must never enter the drop bookkeeping, where it would
			// suppress later coin pickups.
			if ((itemId == ItemID.COINS || itemId == ItemID.PLATINUM) && !context.isDropIntent(itemId))
			{
				long price = itemId == ItemID.PLATINUM ? 1000L : 1L;
				context.addSupplyExpense(itemId, new CoinFlowSession.TrackedItem(itemId, itemName, quantity, price));
				retireSessionGain(context, session, itemId, quantity);
				log.debug("Cash spend: {} x{} = {} gp", itemName, quantity, (long) quantity * price);
				continue;
			}

			// A "Drop" click means the item left for the ground, not the player's
			// stomach: route through the own-drop path regardless of item type.
			// Last-charge teleport jewelry crumbled in the pack is a supply
			// expense; other crumble items (e.g. Ring of recoil) are excluded here
			// because an inventory loss usually means feeding a Ring of suffering,
			// which WeaponChargeTracker expenses separately.
			boolean isConsumable = !context.isDropIntent(itemId)
				&& (ConsumableRegistry.isConsumable(itemId, itemName, itemManager)
				|| ConsumableRegistry.isSkillSink(context.getActiveSkillingSkills(), itemName)
				|| ConsumableRegistry.isLastChargeTeleportJewelry(itemName));

			if (isConsumable)
			{
				long price = priceOf(itemId, itemManager);

				CoinFlowSession.TrackedItem expenseItem =
					new CoinFlowSession.TrackedItem(itemId, itemName, quantity, price);
				context.addSupplyExpense(itemId, expenseItem);

				// Retire matching session gains so a later drop/sale of pre-session
				// stock cannot deduct the already-consumed loot a second time.
				retireSessionGain(context, session, itemId, quantity);

				log.debug("Consumed supply: {} x{} @ {} gp = {} gp",
					itemName, quantity, price, (long) quantity * price);
			}
			else
			{
				// Non-consumable item dropped from inventory (e.g. Coal, Iron ore, logs, gems, Cooking cape)
				int sessionDeductibleQty = 0;
				if (session != null)
				{
					CoinFlowSession.TrackedItem existingGain = session.getTrackedItems().get(itemId);
					if (existingGain != null && existingGain.getRemainingQuantity() > 0)
					{
						sessionDeductibleQty = (int) Math.min(quantity, existingGain.getRemainingQuantity());
						long price = existingGain.getPriceEach();

						CoinFlowSession.TrackedItem droppedItem =
							new CoinFlowSession.TrackedItem(itemId, itemName, sessionDeductibleQty, price);
						context.addDroppedDeduction(itemId, droppedItem);

						log.debug("Dropped item deducted from profit: {} x{} @ {} gp = {} gp",
							itemName, sessionDeductibleQty, price, (long) sessionDeductibleQty * price);
					}
				}

				if (sessionDeductibleQty > 0)
				{
					recentlyDroppedItems.merge(itemId, sessionDeductibleQty, Integer::sum);
				}

				int unacquiredDroppedQty = quantity - sessionDeductibleQty;
				if (unacquiredDroppedQty > 0 && context.getRecentlyDroppedOwnedItems() != null)
				{
					context.getRecentlyDroppedOwnedItems().merge(itemId, unacquiredDroppedQty, Integer::sum);
					log.debug("Dropped owned/banked item tracked to prevent false pickup profit: {} x{}",
						itemName, unacquiredDroppedQty);
				}
			}
		}
	}

	/**
	 * Cancels banker coin/platinum token exchanges (1 token = 1,000 coins) so a
	 * pure currency conversion is neither a spend nor income.
	 */
	static void netCashExchange(Map<Integer, Integer> gains, Map<Integer, Integer> losses)
	{
		netExchange(losses, gains, ItemID.PLATINUM, ItemID.COINS);
		netExchange(losses, gains, ItemID.COINS, ItemID.PLATINUM);
	}

	private static void netExchange(Map<Integer, Integer> losses, Map<Integer, Integer> gains, int lostId, int gainedId)
	{
		int lost = losses.getOrDefault(lostId, 0);
		int gained = gains.getOrDefault(gainedId, 0);
		if (lost <= 0 || gained <= 0)
		{
			return;
		}
		int tokens = lostId == ItemID.PLATINUM ? Math.min(lost, gained / 1000) : Math.min(gained, lost / 1000);
		if (tokens <= 0)
		{
			return;
		}
		int lostMatched = lostId == ItemID.PLATINUM ? tokens : tokens * 1000;
		int gainedMatched = lostId == ItemID.PLATINUM ? tokens * 1000 : tokens;
		subtract(losses, lostId, lostMatched);
		subtract(gains, gainedId, gainedMatched);
		log.debug("Netted currency exchange: {} x{} -> {} x{}", lostId, lostMatched, gainedId, gainedMatched);
	}

	private static void subtract(Map<Integer, Integer> map, int id, int qty)
	{
		int remaining = map.getOrDefault(id, 0) - qty;
		if (remaining <= 0)
		{
			map.remove(id);
		}
		else
		{
			map.put(id, remaining);
		}
	}

	/**
	 * Retires matching session gains consumed in place so a later drop or sale
	 * of identical pre-session stock cannot deduct them a second time.
	 */
	private static void retireSessionGain(ReconciliationContext context, CoinFlowSession session, int itemId, int quantity)
	{
		if (session == null)
		{
			return;
		}
		CoinFlowSession.TrackedItem existingGain = session.getTrackedItems().get(itemId);
		if (existingGain != null && existingGain.getRemainingQuantity() > 0)
		{
			context.markSessionGainConsumed(itemId, Math.min(quantity, existingGain.getRemainingQuantity()));
		}
	}

	/**
	 * Market price with the same fallbacks used for gains: GE price, then the
	 * fixed coin/platinum values, then high alchemy for untradeables.
	 */
	private static long priceOf(int itemId, ItemManager itemManager)
	{
		long price = itemManager.getItemPrice(itemId);
		if (price > 0)
		{
			return price;
		}
		if (itemId == ItemID.COINS)
		{
			return 1;
		}
		if (itemId == ItemID.PLATINUM)
		{
			return 1000;
		}
		ItemComposition comp = itemManager.getItemComposition(itemId);
		return comp != null ? comp.getHaPrice() : 0;
	}
}

package com.coinflow.reconciliation;

import java.util.ArrayList;
import java.util.Map;
import net.runelite.client.game.ItemManager;

/**
 * Handles picking up previously dropped items:
 * 1. For items not gained in the session (e.g. Cooking cape, Spade brought from bank/gear),
 *    cancels them out from rawGains so picking up owned items does not create fake profit.
 * 2. For items gained in the current session (e.g. mined Coal, chopped logs), decrements
 *    recentlyDroppedItems and allows rawGains to restore the deducted profit.
 * 3. For items expensed on drop (Count Drops as Spent), cancels them out from rawGains
 *    and records an expense reversal so the Spent charge is undone.
 */
public class DroppedItemPickupHandler implements ReconciliationHandler
{
	@Override
	public void reconcile(ReconciliationContext context)
	{
		applyDropReconciliation(
			context.getRawGains(),
			context.getRecentlyDroppedItems(),
			context.getRecentlyDroppedOwnedItems(),
			context.getRecentlyExpensedDrops(),
			context.getExpenseReversals(),
			context.getItemManager());
	}

	/**
	 * Applies own-drop reconciliation to a gains map in place. Shared with
	 * non-inventory pickup paths (gem bag, herb sack, seed box, fish barrel,
	 * log basket) which bypass the handler chain.
	 */
	public static void applyDropReconciliation(
		Map<Integer, Integer> rawGains,
		Map<Integer, Integer> recentlyDroppedItems,
		Map<Integer, Integer> recentlyDroppedOwnedItems,
		ItemManager itemManager)
	{
		applyDropReconciliation(rawGains, recentlyDroppedItems, recentlyDroppedOwnedItems,
			null, null, itemManager);
	}

	/**
	 * Variant that also matches expensed drops: matched gains are removed from
	 * {@code rawGains} and the quantities are accumulated into
	 * {@code expenseReversalsOut} for the caller to apply with
	 * {@link com.coinflow.CoinFlowSession#withExpenseReversal}.
	 */
	public static void applyDropReconciliation(
		Map<Integer, Integer> rawGains,
		Map<Integer, Integer> recentlyDroppedItems,
		Map<Integer, Integer> recentlyDroppedOwnedItems,
		Map<Integer, Integer> recentlyExpensedDrops,
		Map<Integer, Long> expenseReversalsOut,
		ItemManager itemManager)
	{
		if (rawGains.isEmpty())
		{
			return;
		}

		// 0. Reconcile expensed drops (Count Drops as Spent):
		// The drop was charged to Spent, so the pickup reverses that charge rather than
		// crediting a gain. Runs first so these never fall through to the legacy maps.
		if (recentlyExpensedDrops != null && !recentlyExpensedDrops.isEmpty())
		{
			for (Map.Entry<Integer, Integer> entry : new ArrayList<>(rawGains.entrySet()))
			{
				int rawId = entry.getKey();
				int gainQty = entry.getValue();
				int canonicalId = itemManager != null ? itemManager.canonicalize(rawId) : rawId;

				int pending = recentlyExpensedDrops.getOrDefault(canonicalId, 0);
				int keyToUse = canonicalId;
				if (pending == 0 && canonicalId != rawId)
				{
					pending = recentlyExpensedDrops.getOrDefault(rawId, 0);
					keyToUse = rawId;
				}

				if (pending > 0)
				{
					int match = Math.min(gainQty, pending);
					if (pending <= match)
					{
						recentlyExpensedDrops.remove(keyToUse);
					}
					else
					{
						recentlyExpensedDrops.put(keyToUse, pending - match);
					}

					if (expenseReversalsOut != null)
					{
						expenseReversalsOut.merge(canonicalId, (long) match, Long::sum);
					}

					int remainingGain = gainQty - match;
					if (remainingGain <= 0)
					{
						rawGains.remove(rawId);
					}
					else
					{
						rawGains.put(rawId, remainingGain);
					}
				}
			}
		}

		if (rawGains.isEmpty())
		{
			return;
		}

		// 1. Reconcile owned/banked items that were dropped:
		// These were never credited as profit or deducted on drop, so picking them back up
		// must NOT be credited as loot/profit. Remove them from rawGains.
		if (recentlyDroppedOwnedItems != null && !recentlyDroppedOwnedItems.isEmpty())
		{
			for (Map.Entry<Integer, Integer> entry : new ArrayList<>(rawGains.entrySet()))
			{
				int rawId = entry.getKey();
				int gainQty = entry.getValue();
				int canonicalId = itemManager != null ? itemManager.canonicalize(rawId) : rawId;

				int droppedOwned = recentlyDroppedOwnedItems.getOrDefault(canonicalId, 0);
				int keyToUse = canonicalId;
				if (droppedOwned == 0 && canonicalId != rawId)
				{
					droppedOwned = recentlyDroppedOwnedItems.getOrDefault(rawId, 0);
					keyToUse = rawId;
				}

				if (droppedOwned > 0)
				{
					int match = Math.min(gainQty, droppedOwned);
					if (droppedOwned <= match)
					{
						recentlyDroppedOwnedItems.remove(keyToUse);
					}
					else
					{
						recentlyDroppedOwnedItems.put(keyToUse, droppedOwned - match);
					}

					int remainingGain = gainQty - match;
					if (remainingGain <= 0)
					{
						rawGains.remove(rawId);
					}
					else
					{
						rawGains.put(rawId, remainingGain);
					}
				}
			}
		}

		// 2. Reconcile session-gained items that were dropped:
		// Decrement recentlyDroppedItems so the remaining gain restores the session deduction without staying pending.
		if (recentlyDroppedItems != null && !recentlyDroppedItems.isEmpty() && !rawGains.isEmpty())
		{
			for (Map.Entry<Integer, Integer> entry : rawGains.entrySet())
			{
				int rawId = entry.getKey();
				int gainQty = entry.getValue();
				int canonicalId = itemManager != null ? itemManager.canonicalize(rawId) : rawId;

				Integer droppedQty = recentlyDroppedItems.get(canonicalId);
				int keyToUse = canonicalId;
				if (droppedQty == null && canonicalId != rawId)
				{
					droppedQty = recentlyDroppedItems.get(rawId);
					keyToUse = rawId;
				}

				if (droppedQty != null)
				{
					if (droppedQty <= gainQty)
					{
						recentlyDroppedItems.remove(keyToUse);
					}
					else
					{
						recentlyDroppedItems.put(keyToUse, droppedQty - gainQty);
					}
				}
			}
		}
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowSession;
import com.coinflow.ConsumableRegistry;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.client.game.ItemManager;

/**
 * Handles multi-bite food portions (e.g. Summer pie -> Half a summer pie, pizzas, cakes),
 * consuming whole items and attributing portion supply expenses without marking portions as loot.
 */
public class FoodPortionHandler implements ReconciliationHandler
{
	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();

		if (rawLosses.isEmpty())
		{
			return;
		}

		List<Integer> lostIds = new ArrayList<>(rawLosses.keySet());
		for (int lostId : lostIds)
		{
			int canonicalLostId = itemManager.canonicalize(lostId);
			String lostName = context.getItemName(canonicalLostId);

			Integer portionGainedId = null;
			for (int gainedId : rawGains.keySet())
			{
				int canonicalGainedId = itemManager.canonicalize(gainedId);
				String gainedName = context.getItemName(canonicalGainedId);
				if (ConsumableRegistry.isFoodPortion(gainedName, lostName))
				{
					portionGainedId = gainedId;
					break;
				}
			}

			if (portionGainedId != null)
			{
				int lostQty = rawLosses.get(lostId);
				int gainedQty = rawGains.get(portionGainedId);
				int portions = Math.min(lostQty, gainedQty);

				if (gainedQty <= portions)
				{
					rawGains.remove(portionGainedId);
				}
				else
				{
					rawGains.put(portionGainedId, gainedQty - portions);
				}

				if (lostQty <= portions)
				{
					rawLosses.remove(lostId);
				}
				else
				{
					rawLosses.put(lostId, lostQty - portions);
				}

				long wholePrice = itemManager.getItemPrice(canonicalLostId);
				int portionsInWhole = lostName.toLowerCase(java.util.Locale.ROOT).contains("cake") ? 3 : 2;
				long portionPrice = Math.max(1L, wholePrice / portionsInWhole);

				// Move purchase basis with the food: the eaten portion's share
				// is expensed at cost, the rest stays on the leftover portion.
				long basisCost = 0;
				int basisPortions = 0;
				com.coinflow.GrandExchangeTracker tracker = context.getGrandExchangeTracker();
				if (tracker != null)
				{
					long[] result = tracker.reconcilePotionBasis(
						java.util.Collections.singletonList(
							new com.coinflow.GrandExchangeTracker.PotionBottle(canonicalLostId, portionsInWhole, portions)),
						java.util.Collections.singletonList(
							new com.coinflow.GrandExchangeTracker.PotionBottle(
								itemManager.canonicalize(portionGainedId), portionsInWhole - 1, portions)),
						portions);
					basisCost = result[0];
					basisPortions = (int) result[1];
				}

				long expenseTotal = basisCost
					+ (long) Math.max(0, portions - basisPortions) * portionPrice;
				String expenseName = lostName + " (portion)";
				context.addFractionalSupplyExpense(canonicalLostId,
					new CoinFlowSession.TrackedItem(canonicalLostId, expenseName, portions,
						expenseTotal / portions));
			}
		}
	}
}

package com.coinflow.reconciliation;

import java.util.ArrayList;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/**
 * Handles unequipped gear moved to inventory or equipped gear moved to equipment slots,
 * canceling out spurious gains and losses across inventory and worn equipment diffs.
 */
public class GearSwapHandler implements ReconciliationHandler
{
	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		Map<Integer, Integer> recentlyUnequippedItems = context.getRecentlyUnequippedItems();
		Map<Integer, Integer> recentlyEquippedItems = context.getRecentlyEquippedItems();

		// 1. Subtract any items that were just unequipped from gear slots
		if (!recentlyUnequippedItems.isEmpty())
		{
			for (Map.Entry<Integer, Integer> unequipped : new ArrayList<>(recentlyUnequippedItems.entrySet()))
			{
				int unequippedId = unequipped.getKey();
				int unequippedQty = unequipped.getValue();

				Integer gainedQty = rawGains.get(unequippedId);
				if (gainedQty != null)
				{
					int matched = Math.min(gainedQty, unequippedQty);
					int netGain = gainedQty - matched;
					if (netGain <= 0)
					{
						rawGains.remove(unequippedId);
					}
					else
					{
						rawGains.put(unequippedId, netGain);
					}

					int remainingUnequipped = unequippedQty - matched;
					if (remainingUnequipped <= 0)
					{
						recentlyUnequippedItems.remove(unequippedId);
					}
					else
					{
						recentlyUnequippedItems.put(unequippedId, remainingUnequipped);
					}

					if (context.getPendingWornAmmoExpenses() != null)
					{
						int canonicalUnequippedId = context.getItemManager() != null
							? context.getItemManager().canonicalize(unequippedId)
							: unequippedId;
						Integer pending = context.getPendingWornAmmoExpenses().get(canonicalUnequippedId);
						int keyToUse = canonicalUnequippedId;
						if (pending == null && canonicalUnequippedId != unequippedId)
						{
							pending = context.getPendingWornAmmoExpenses().get(unequippedId);
							keyToUse = unequippedId;
						}
						if (pending != null)
						{
							if (pending <= matched)
							{
								context.getPendingWornAmmoExpenses().remove(keyToUse);
							}
							else
							{
								context.getPendingWornAmmoExpenses().put(keyToUse, pending - matched);
							}
						}
					}
				}
			}
		}

		// 2. Also check against previousEquipmentSnapshot if INV dispatched before WORN
		if (context.getPreviousEquipmentSnapshot() != null && !rawGains.isEmpty())
		{
			ItemContainer currentEquip = context.getCurrentEquipContainer();
			for (Map.Entry<Integer, Integer> entry : new ArrayList<>(rawGains.entrySet()))
			{
				int rawId = entry.getKey();
				int gainQty = entry.getValue();
				int canonicalId = context.getItemManager().canonicalize(rawId);

				int equippedQty = context.getPreviousEquipmentSnapshot().getItems().getOrDefault(rawId, 0);
				if (equippedQty == 0 && canonicalId != rawId)
				{
					equippedQty = context.getPreviousEquipmentSnapshot().getItems().getOrDefault(canonicalId, 0);
				}

				if (equippedQty > 0)
				{
					int currentWornQty = 0;
					if (currentEquip != null)
					{
						Item[] wornItems = currentEquip.getItems();
						if (wornItems != null)
						{
							for (Item item : wornItems)
							{
								if (item != null && (item.getId() == rawId || item.getId() == canonicalId))
								{
									currentWornQty += item.getQuantity();
								}
							}
						}
					}

					int unequipped = Math.max(0, equippedQty - currentWornQty);
					if (unequipped > 0)
					{
						int match = Math.min(gainQty, unequipped);
						if (gainQty <= match)
						{
							rawGains.remove(rawId);
						}
						else
						{
							rawGains.put(rawId, gainQty - match);
						}

						if (context.getMatchedUnequipsThisTick() != null)
						{
							context.getMatchedUnequipsThisTick().merge(canonicalId, match, Integer::sum);
						}

						if (context.getPendingWornAmmoExpenses() != null)
						{
							Integer pending = context.getPendingWornAmmoExpenses().get(canonicalId);
							int keyToUse = canonicalId;
							if (pending == null && canonicalId != rawId)
							{
								pending = context.getPendingWornAmmoExpenses().get(rawId);
								keyToUse = rawId;
							}
							if (pending != null)
							{
								if (pending <= match)
								{
									context.getPendingWornAmmoExpenses().remove(keyToUse);
								}
								else
								{
									context.getPendingWornAmmoExpenses().put(keyToUse, pending - match);
								}
							}
						}
					}
				}
			}
		}

		// 3. Subtract any items that were just equipped into gear slots
		if (!recentlyEquippedItems.isEmpty())
		{
			for (Map.Entry<Integer, Integer> equipped : new ArrayList<>(recentlyEquippedItems.entrySet()))
			{
				int equippedId = equipped.getKey();
				int equippedQty = equipped.getValue();

				Integer lostQty = rawLosses.get(equippedId);
				if (lostQty != null)
				{
					int matched = Math.min(lostQty, equippedQty);
					int netLost = lostQty - matched;
					if (netLost <= 0)
					{
						rawLosses.remove(equippedId);
					}
					else
					{
						rawLosses.put(equippedId, netLost);
					}

					int remainingEquipped = equippedQty - matched;
					if (remainingEquipped <= 0)
					{
						recentlyEquippedItems.remove(equippedId);
					}
					else
					{
						recentlyEquippedItems.put(equippedId, remainingEquipped);
					}
				}
			}
		}

		// 4. Also check against current equipment if INV dispatched before WORN
		if (!rawLosses.isEmpty())
		{
			ItemContainer currentEquip = context.getCurrentEquipContainer();
			if (currentEquip != null && context.getPreviousEquipmentSnapshot() != null)
			{
				for (Map.Entry<Integer, Integer> entry : new ArrayList<>(rawLosses.entrySet()))
				{
					int rawId = entry.getKey();
					int lostQty = entry.getValue();
					int canonicalId = context.getItemManager().canonicalize(rawId);

					int prevWornQty = context.getPreviousEquipmentSnapshot().getItems().getOrDefault(rawId, 0);
					if (prevWornQty == 0 && canonicalId != rawId)
					{
						prevWornQty = context.getPreviousEquipmentSnapshot().getItems().getOrDefault(canonicalId, 0);
					}

					int currentWornQty = 0;
					Item[] wornItems = currentEquip.getItems();
					if (wornItems != null)
					{
						for (Item item : wornItems)
						{
							if (item != null && (item.getId() == rawId || item.getId() == canonicalId))
							{
								currentWornQty += item.getQuantity();
							}
						}
					}

					int newlyEquipped = Math.max(0, currentWornQty - prevWornQty);
					if (newlyEquipped > 0)
					{
						int match = Math.min(lostQty, newlyEquipped);
						if (lostQty <= match)
						{
							rawLosses.remove(rawId);
						}
						else
						{
							rawLosses.put(rawId, lostQty - match);
						}
					}
				}
			}
		}
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowSession;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Detects High Alchemy casts: matches coin gains against items lost whose High Alchemy
 * value produces the exact coin quantity. Converts session drops or banked items into
 * supplies/deductions according to True Inventory Accounting.
 */
@Slf4j
public class HighAlchemyHandler implements ReconciliationHandler
{
	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();
		CoinFlowSession session = context.getSession();

		if (!rawGains.containsKey(ItemID.COINS))
		{
			return;
		}

		// Prevent false positives from coincidental monster coin drops or shop sales:
		// Require either Nature rune consumption or a verified alchemy action/context.
		boolean hasNatureRuneLoss = rawLosses.containsKey(ItemID.NATURERUNE);
		if (!hasNatureRuneLoss && !context.isAlchemy())
		{
			return;
		}

		int coinsGained = rawGains.get(ItemID.COINS);
		Integer alchedLostId = null;
		int alchedQty = 0;
		long alchedItemMarketPrice = 0L;
		String alchedItemName = null;

		// Deterministic candidate scan: sorted ids, prefer the smallest alch qty
		// (a real cast alchemises one item per tick; a partial-stack match also
		// covers an alched item that was lost for another reason in the same tick).
		java.util.List<Integer> sortedLossIds = new java.util.ArrayList<>(rawLosses.keySet());
		java.util.Collections.sort(sortedLossIds);
		int bestAlchQty = Integer.MAX_VALUE;

		for (int rawLostId : sortedLossIds)
		{
			int lostQty = rawLosses.get(rawLostId);
			int canonicalLostId = itemManager.canonicalize(rawLostId);

			if (canonicalLostId == ItemID.FIRERUNE || canonicalLostId == ItemID.COINS)
			{
				continue;
			}

			ItemComposition comp = itemManager.getItemComposition(canonicalLostId);
			if (comp == null)
			{
				continue;
			}

			int haPrice = comp.getHaPrice();
			if (haPrice <= 0 || coinsGained % haPrice != 0)
			{
				continue;
			}

			int quotient = coinsGained / haPrice;
			int candidateAlchQty;
			if (canonicalLostId == ItemID.NATURERUNE)
			{
				// The casting rune may come from the same stack: allow alch qty of
				// lostQty - 1 (one nature spent casting) or lostQty.
				if (lostQty >= 2 && quotient == lostQty - 1)
				{
					candidateAlchQty = quotient;
				}
				else if (quotient == lostQty)
				{
					candidateAlchQty = quotient;
				}
				else
				{
					continue;
				}
			}
			else if (quotient >= 1 && quotient <= lostQty)
			{
				candidateAlchQty = quotient;
			}
			else
			{
				continue;
			}

			if (candidateAlchQty < bestAlchQty)
			{
				bestAlchQty = candidateAlchQty;
				alchedLostId = rawLostId;
				alchedQty = candidateAlchQty;
				alchedItemMarketPrice = itemManager.getItemPrice(canonicalLostId);
				if (alchedItemMarketPrice <= 0)
				{
					alchedItemMarketPrice = haPrice;
				}
				alchedItemName = comp.getName();
			}
		}

		if (alchedLostId != null)
		{
			int canonicalLostId = itemManager.canonicalize(alchedLostId);
			ItemComposition comp = itemManager.getItemComposition(canonicalLostId);
			int haPrice = comp != null ? comp.getHaPrice() : (int) (coinsGained / Math.max(1, alchedQty));

			// Clean up rawLosses: if casting rune was used from the same stack (nature runes), keep 1 for supply expenses
			int currentLoss = rawLosses.getOrDefault(alchedLostId, 0);
			if (currentLoss <= alchedQty)
			{
				rawLosses.remove(alchedLostId);
			}
			else
			{
				rawLosses.put(alchedLostId, currentLoss - alchedQty);
			}

			int availableInSession = 0;
			if (session != null)
			{
				CoinFlowSession.TrackedItem sessionDrop = session.getTrackedItems().get(canonicalLostId);
				if (sessionDrop != null)
				{
					availableInSession = (int) Math.min(Integer.MAX_VALUE, sessionDrop.getRemainingQuantity());
				}
			}

			int sessionDeductibleQty = Math.min(alchedQty, availableInSession);
			if (sessionDeductibleQty > 0)
			{
				CoinFlowSession.TrackedItem sessionDrop = session.getTrackedItems().get(canonicalLostId);
				long dropPrice = sessionDrop != null ? sessionDrop.getPriceEach() : alchedItemMarketPrice;
				CoinFlowSession.TrackedItem deductItem = new CoinFlowSession.TrackedItem(
					canonicalLostId, alchedItemName, sessionDeductibleQty, dropPrice
				);
				context.addDroppedDeduction(canonicalLostId, deductItem);
			}

			int bankedQty = alchedQty - sessionDeductibleQty;
			if (bankedQty > 0)
			{
				CoinFlowSession.TrackedItem itemExpense = new CoinFlowSession.TrackedItem(
					canonicalLostId, alchedItemName, bankedQty, alchedItemMarketPrice
				);
				context.addSupplyExpense(canonicalLostId, itemExpense);
			}

			long unitMargin = haPrice - alchedItemMarketPrice;
			long totalMargin = unitMargin * alchedQty;

			context.setAlchedDropItemId(ItemID.COINS);
			context.setAlchedTotalMargin(totalMargin);
			context.setAlchedItemRawId(alchedLostId);

			log.debug("Alchemised: {} x{} (ha: {} gp, market: {} gp, sessionConverted: {}, banked: {}, margin: {} gp)",
				alchedItemName, alchedQty, haPrice, alchedItemMarketPrice, sessionDeductibleQty, bankedQty, totalMargin);
		}
	}
}

package com.coinflow.reconciliation;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Executes the ordered pipeline of item reconciliation handlers.
 * Resolves gear swaps, alchemy, potions, portions, cooking, supplies, and drops
 * into final gains, supply expenses, and dropped deductions.
 */
@Singleton
public class InventoryReconciliationEngine
{
	private final List<ReconciliationHandler> handlers;

	@Inject
	public InventoryReconciliationEngine()
	{
		this.handlers = Collections.unmodifiableList(Arrays.asList(
			new GearSwapHandler(),
			new DroppedItemPickupHandler(),
			new ItemNotingHandler(),
			new HighAlchemyHandler(),
			new PotionDoseHandler(),
			new ChargeDegradationHandler(),
			new FoodPortionHandler(),
			new ProcessingHandler(),
			new ConsumablesAndDropsHandler()
		));
	}

	public InventoryReconciliationEngine(List<ReconciliationHandler> customHandlers)
	{
		this.handlers = Collections.unmodifiableList(customHandlers);
	}

	/**
	 * Runs the reconciliation pipeline on the given context.
	 *
	 * @param context the mutable reconciliation context
	 */
	public void reconcile(ReconciliationContext context)
	{
		for (ReconciliationHandler handler : handlers)
		{
			handler.reconcile(context);
		}
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowSession;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Reconciles items converted between noted and unnoted forms (e.g., Tool Leprechaun noting
 * harvested crops, Phials unnoting planks/bones in Rimmington, or Piles in the Wilderness).
 *
 * Prevents noting owned or harvested items from triggering duplicate gains / false profit,
 * prevents unnoting items from triggering fake loot drops, and attributes any unnoting / noting
 * service fees (e.g. 5 gp each charged by Phials/Piles) to supply expenses.
 */
@Slf4j
public class ItemNotingHandler implements ReconciliationHandler
{
	private static final int DEFAULT_UNNOTING_FEE_EACH = 5;

	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();

		if (rawLosses.isEmpty() || rawGains.isEmpty())
		{
			return;
		}

		int totalConvertedItems = 0;

		List<Integer> lostKeys = new ArrayList<>(rawLosses.keySet());
		for (int lostId : lostKeys)
		{
			if (rawGains.isEmpty())
			{
				break;
			}

			Integer lostQtyBoxed = rawLosses.get(lostId);
			if (lostQtyBoxed == null || lostQtyBoxed <= 0)
			{
				continue;
			}
			int lostQty = lostQtyBoxed;

			int canonicalLostId = itemManager != null ? itemManager.canonicalize(lostId) : lostId;
			if (canonicalLostId <= 0 || canonicalLostId == ItemID.COINS)
			{
				continue;
			}

			while (lostQty > 0 && !rawGains.isEmpty())
			{
				Integer matchedGainedId = null;
				int gainedQty = 0;

				for (Map.Entry<Integer, Integer> gainedEntry : rawGains.entrySet())
				{
					int gainedId = gainedEntry.getKey();
					if (gainedId == lostId)
					{
						continue;
					}

					int canonicalGainedId = itemManager != null ? itemManager.canonicalize(gainedId) : gainedId;
					if (canonicalLostId == canonicalGainedId && gainedEntry.getValue() > 0)
					{
						matchedGainedId = gainedId;
						gainedQty = gainedEntry.getValue();
						break;
					}
				}

				if (matchedGainedId == null)
				{
					break;
				}

				int matchQty = Math.min(lostQty, gainedQty);
				if (matchQty > 0)
				{
					totalConvertedItems += matchQty;
					String itemName = context.getItemName(canonicalLostId);
					log.debug("Reconciled note/unnote swap: {} x{} (lost raw {}, gained raw {})",
						itemName, matchQty, lostId, matchedGainedId);

					lostQty -= matchQty;
					if (lostQty <= 0)
					{
						rawLosses.remove(lostId);
					}
					else
					{
						rawLosses.put(lostId, lostQty);
					}

					if (gainedQty <= matchQty)
					{
						rawGains.remove(matchedGainedId);
					}
					else
					{
						rawGains.put(matchedGainedId, gainedQty - matchQty);
					}
				}
				else
				{
					break;
				}
			}
		}

		// Reconcile service fee (e.g. 5 gp each charged by Phials or Piles).
		// Only attribute a coin loss as a fee when a noting-service interaction was
		// recently clicked — otherwise coincidental coin losses in the same tick as a
		// note swap (or free noting at the Tool Leprechaun) get eaten as fake fees.
		if (totalConvertedItems > 0 && context.isNotingService() && !rawLosses.isEmpty())
		{
			Integer coinsLostKey = null;
			int coinsLostQty = 0;

			for (Map.Entry<Integer, Integer> entry : rawLosses.entrySet())
			{
				int canonicalId = itemManager != null ? itemManager.canonicalize(entry.getKey()) : entry.getKey();
				if (canonicalId == ItemID.COINS)
				{
					coinsLostKey = entry.getKey();
					coinsLostQty = entry.getValue();
					break;
				}
			}

			if (coinsLostKey != null && coinsLostQty > 0)
			{
				int maxExpectedFee = totalConvertedItems * DEFAULT_UNNOTING_FEE_EACH;
				int feeDeducted = Math.min(coinsLostQty, maxExpectedFee);

				if (feeDeducted > 0)
				{
					String coinsName = context.getItemName(ItemID.COINS);
					if (coinsName == null || coinsName.isEmpty())
					{
						coinsName = "Coins";
					}

					context.addSupplyExpense(
						ItemID.COINS,
						new CoinFlowSession.TrackedItem(ItemID.COINS, coinsName, feeDeducted, 1L)
					);
					log.debug("Attributed noting/unnoting fee: {} gp", feeDeducted);

					if (coinsLostQty <= feeDeducted)
					{
						rawLosses.remove(coinsLostKey);
					}
					else
					{
						rawLosses.put(coinsLostKey, coinsLostQty - feeDeducted);
					}
				}
			}
		}
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowSession;
import com.coinflow.ConsumableRegistry;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Handles potion dose stepping (e.g. 4-dose -> 3-dose, 1-dose -> empty vial)
 * and potion dose combining/decanting (e.g. 3-dose + 3-dose -> 4-dose + 2-dose),
 * pricing genuinely consumed doses without counting empty vials or decanted doses as loot/expenses.
 */
public class PotionDoseHandler implements ReconciliationHandler
{
	private static class PotionEntry
	{
		final int itemId;
		final int canonicalId;
		final int dose;
		final int qty;

		PotionEntry(int itemId, int canonicalId, int dose, int qty)
		{
			this.itemId = itemId;
			this.canonicalId = canonicalId;
			this.dose = dose;
			this.qty = qty;
		}
	}

	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();

		if (rawLosses.isEmpty())
		{
			return;
		}

		// Group lost potions by baseName
		Map<String, List<PotionEntry>> lostByBase = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : rawLosses.entrySet())
		{
			int rawId = entry.getKey();
			int qty = entry.getValue();
			if (qty <= 0)
			{
				continue;
			}
			int canonicalId = itemManager.canonicalize(rawId);
			if (context.isDropIntent(canonicalId))
			{
				// Dropped, not drunk: leave for the own-drop path
				continue;
			}
			String name = context.getItemName(canonicalId);
			ConsumableRegistry.PotionDose potion = ConsumableRegistry.parsePotion(name);
			if (potion != null)
			{
				String key = potion.getBaseName().toLowerCase(Locale.ROOT);
				lostByBase.computeIfAbsent(key, k -> new ArrayList<>())
					.add(new PotionEntry(rawId, canonicalId, potion.getDose(), qty));
			}
		}

		if (lostByBase.isEmpty())
		{
			return;
		}

		// Group gained potions by baseName
		Map<String, List<PotionEntry>> gainedByBase = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : rawGains.entrySet())
		{
			int rawId = entry.getKey();
			int qty = entry.getValue();
			if (qty <= 0)
			{
				continue;
			}
			int canonicalId = itemManager.canonicalize(rawId);
			String name = context.getItemName(canonicalId);
			ConsumableRegistry.PotionDose potion = ConsumableRegistry.parsePotion(name);
			if (potion != null)
			{
				String key = potion.getBaseName().toLowerCase(Locale.ROOT);
				gainedByBase.computeIfAbsent(key, k -> new ArrayList<>())
					.add(new PotionEntry(rawId, canonicalId, potion.getDose(), qty));
			}
		}

		// Process each baseName with lost doses
		for (Map.Entry<String, List<PotionEntry>> baseEntry : lostByBase.entrySet())
		{
			String baseKey = baseEntry.getKey();
			List<PotionEntry> lostList = baseEntry.getValue();
			List<PotionEntry> gainedList = gainedByBase.getOrDefault(baseKey, Collections.emptyList());

			int totalLostDoses = 0;
			int totalLostBottles = 0;
			int sampleCanonicalId = -1;
			int sampleDose = -1;
			String sampleBaseName = null;

			for (PotionEntry p : lostList)
			{
				totalLostDoses += p.dose * p.qty;
				totalLostBottles += p.qty;
				if (p.dose > sampleDose)
				{
					sampleCanonicalId = p.canonicalId;
					sampleDose = p.dose;
					ConsumableRegistry.PotionDose parsed = ConsumableRegistry.parsePotion(context.getItemName(p.canonicalId));
					if (parsed != null)
					{
						sampleBaseName = parsed.getBaseName();
					}
				}
			}

			int totalGainedDoses = 0;
			int totalGainedBottles = 0;
			for (PotionEntry p : gainedList)
			{
				totalGainedDoses += p.dose * p.qty;
				totalGainedBottles += p.qty;
			}

			if (totalLostDoses <= 0)
			{
				continue;
			}

			int dosesConsumed = Math.max(0, totalLostDoses - totalGainedDoses);
			int vialsFreed = totalLostBottles - totalGainedBottles;

			// Remove all lost potion items: they transformed into other dose forms
			// (or were consumed as doses), so they are never a raw supply loss.
			for (PotionEntry p : lostList)
			{
				rawLosses.remove(p.itemId);
			}

			if (totalLostDoses >= totalGainedDoses)
			{
				// Decant and/or consumption of this potion: suppress all gains of this base
				for (PotionEntry p : gainedList)
				{
					rawGains.remove(p.itemId);
				}
			}
			else
			{
				// More doses gained than lost (e.g. drank a dose while looting or
				// decanting the same potion in the same tick): suppress only the
				// dose-equivalent of the lost potions, highest dose first.
				// Leftover gained doses remain as legitimate profit.
				int dosesToSuppress = totalLostDoses;
				List<PotionEntry> descendingDose = new ArrayList<>(gainedList);
				descendingDose.sort((a, b) -> Integer.compare(b.dose, a.dose));
				for (PotionEntry p : descendingDose)
				{
					if (dosesToSuppress <= 0)
					{
						break;
					}
					int suppressQty = Math.min(p.qty, dosesToSuppress / p.dose);
					if (suppressQty <= 0)
					{
						continue;
					}
					dosesToSuppress -= suppressQty * p.dose;
					int remaining = rawGains.getOrDefault(p.itemId, 0) - suppressQty;
					if (remaining <= 0)
					{
						rawGains.remove(p.itemId);
					}
					else
					{
						rawGains.put(p.itemId, remaining);
					}
				}
			}

			// Drain purchase basis as bottles change form or are drunk: the cost
			// share of doses still held moves to the gained dose forms so a
			// consumed bottle's basis can't attach to a later sale of an
			// identical pre-session potion. Runs even for pure decants.
			long basisCost = 0;
			int basisDoses = 0;
			com.coinflow.GrandExchangeTracker tracker = context.getGrandExchangeTracker();
			if (tracker != null)
			{
				List<com.coinflow.GrandExchangeTracker.PotionBottle> lostBottles = new ArrayList<>();
				for (PotionEntry p : lostList)
				{
					lostBottles.add(new com.coinflow.GrandExchangeTracker.PotionBottle(p.canonicalId, p.dose, p.qty));
				}
				List<com.coinflow.GrandExchangeTracker.PotionBottle> gainedBottles = new ArrayList<>();
				for (PotionEntry p : gainedList)
				{
					gainedBottles.add(new com.coinflow.GrandExchangeTracker.PotionBottle(p.canonicalId, p.dose, p.qty));
				}
				long[] result = tracker.reconcilePotionBasis(lostBottles, gainedBottles, dosesConsumed);
				basisCost = result[0];
				basisDoses = (int) result[1];
			}

			// If doses were consumed, record supply expense
			if (dosesConsumed > 0 && sampleCanonicalId != -1 && sampleDose > 0)
			{
				long potionPrice = itemManager.getItemPrice(sampleCanonicalId);
				long dosePrice = Math.max(1L, potionPrice / sampleDose);

				long expenseTotal = basisCost + (long) Math.max(0, dosesConsumed - basisDoses) * dosePrice;
				String expenseName = (sampleBaseName != null ? sampleBaseName : "Potion") + " (dose)";
				context.addFractionalSupplyExpense(sampleCanonicalId,
					new CoinFlowSession.TrackedItem(sampleCanonicalId, expenseName, dosesConsumed,
						expenseTotal / dosesConsumed));
			}

			// Reconcile empty vials if vials were freed
			if (vialsFreed > 0)
			{
				Integer vialGainId = null;
				for (int gainedId : rawGains.keySet())
				{
					int canonicalGainedId = itemManager.canonicalize(gainedId);
					if (canonicalGainedId == ItemID.VIAL_EMPTY || "Vial".equalsIgnoreCase(context.getItemName(canonicalGainedId)))
					{
						vialGainId = gainedId;
						break;
					}
				}

				if (vialGainId != null)
				{
					int vialQty = rawGains.get(vialGainId);
					if (vialQty <= vialsFreed)
					{
						rawGains.remove(vialGainId);
					}
					else
					{
						rawGains.put(vialGainId, vialQty - vialsFreed);
					}
				}
			}
			// If bottles were consolidated from empty vials:
			else if (vialsFreed < 0)
			{
				int vialsNeeded = -vialsFreed;
				Integer vialLostId = null;
				for (int lostId : rawLosses.keySet())
				{
					int canonicalLostId = itemManager.canonicalize(lostId);
					if (canonicalLostId == ItemID.VIAL_EMPTY || "Vial".equalsIgnoreCase(context.getItemName(canonicalLostId)))
					{
						vialLostId = lostId;
						break;
					}
				}
				if (vialLostId != null)
				{
					int vialQty = rawLosses.get(vialLostId);
					if (vialQty <= vialsNeeded)
					{
						rawLosses.remove(vialLostId);
					}
					else
					{
						rawLosses.put(vialLostId, vialQty - vialsNeeded);
					}
				}
			}
		}
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowSession;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Unified production and processing reconciliation handler:
 * Handles Cooking, Fletching, Herblore, Crafting, Smithing, and Magic conversions.
 * Deducts session-gathered materials to prevent double profit, and records banked
 * ingredients as supply expenses so net profit accurately reflects the margin.
 */
@Slf4j
public class ProcessingHandler implements ReconciliationHandler
{
	@Override
	public void reconcile(ReconciliationContext context)
	{
		Map<Integer, Integer> rawGains = context.getRawGains();
		Map<Integer, Integer> rawLosses = context.getRawLosses();
		ItemManager itemManager = context.getItemManager();
		CoinFlowSession session = context.getSession();

		if (rawLosses.isEmpty() || rawGains.isEmpty())
		{
			return;
		}

		Map<Integer, Integer> availableSessionGains = new HashMap<>();
		if (session != null)
		{
			for (Map.Entry<Integer, CoinFlowSession.TrackedItem> entry : session.getTrackedItems().entrySet())
			{
				availableSessionGains.put(entry.getKey(), (int) Math.min(Integer.MAX_VALUE, entry.getValue().getRemainingQuantity()));
			}
		}

		Map<Integer, Integer> unmatchedGains = new HashMap<>(rawGains);

		List<Integer> lostKeys = new ArrayList<>(rawLosses.keySet());
		for (int rawLostId : lostKeys)
		{
			Integer lostQty = rawLosses.get(rawLostId);
			if (lostQty == null || lostQty <= 0)
			{
				continue;
			}

			int canonicalRawLostId = itemManager.canonicalize(rawLostId);
			String rawLostName = context.getItemName(canonicalRawLostId);
			if (context.isIgnored(rawLostName))
			{
				continue;
			}

			List<Integer> gainKeys = new ArrayList<>(unmatchedGains.keySet());
			for (int rawGainedId : gainKeys)
			{
				Integer gainedQty = unmatchedGains.get(rawGainedId);
				if (gainedQty == null || gainedQty <= 0)
				{
					continue;
				}

				int canonicalGainedId = itemManager.canonicalize(rawGainedId);
				String gainedName = context.getItemName(canonicalGainedId);
				if (context.isIgnored(gainedName))
				{
					continue;
				}

				ProcessingPatternRegistry.MatchResult match =
					ProcessingPatternRegistry.match(rawLostName, gainedName, gainedQty);

				if (match == null)
				{
					continue;
				}

				int primaryNeeded = match.getPrimaryConsumedQty();
				if (primaryNeeded <= 0)
				{
					continue;
				}

				int primaryToConsume = Math.min(lostQty, primaryNeeded);

				// 1. Apply primary material cost
				applyMaterialCost(
					context,
					canonicalRawLostId,
					rawLostName,
					primaryToConsume,
					availableSessionGains,
					session,
					itemManager
				);

				// Exempt glassblown products (like vials/glasses) from byproduct suppression
				if (rawLostName.equalsIgnoreCase("molten glass"))
				{
					context.addExemptProduct(canonicalGainedId);
				}

				// 2. Decrement unmatched gains and purge failure junk
				if (match.isBurntJunk())
				{
					Integer currentGained = rawGains.get(rawGainedId);
					if (currentGained != null)
					{
						if (currentGained <= gainedQty)
						{
							rawGains.remove(rawGainedId);
						}
						else
						{
							rawGains.put(rawGainedId, currentGained - gainedQty);
						}
					}
					unmatchedGains.remove(rawGainedId);
				}
				else
				{
					int satisfiedGained = primaryNeeded == primaryToConsume
						? gainedQty
						: Math.max(1, (int) Math.floor((double) primaryToConsume * gainedQty / primaryNeeded));

					int remGained = gainedQty - satisfiedGained;
					if (remGained <= 0)
					{
						unmatchedGains.remove(rawGainedId);
					}
					else
					{
						unmatchedGains.put(rawGainedId, remGained);
					}
				}

				// 3. Consume secondary ingredients if present in rawLosses
				if (!match.getSecondariesNeeded().isEmpty())
				{
					for (Map.Entry<String, Integer> secEntry : match.getSecondariesNeeded().entrySet())
					{
						consumeSecondaryIngredient(
							context,
							rawLosses,
							secEntry.getKey(),
							secEntry.getValue(),
							availableSessionGains,
							session,
							itemManager
						);
					}
				}
				else if (match.isPotionFinishing())
				{
					consumeAccompanyingSecondary(
						context,
						rawLosses,
						rawLostId,
						primaryToConsume,
						availableSessionGains,
						session,
						itemManager
					);
				}

				// 4. Update lost quantity
				lostQty -= primaryToConsume;
				if (lostQty <= 0)
				{
					rawLosses.remove(rawLostId);
					break;
				}
				else
				{
					rawLosses.put(rawLostId, lostQty);
				}
			}
		}
	}

	private void consumeSecondaryIngredient(
		ReconciliationContext context,
		Map<Integer, Integer> rawLosses,
		String ingredientName,
		int quantityNeeded,
		Map<Integer, Integer> availableSessionGains,
		CoinFlowSession session,
		ItemManager itemManager)
	{
		for (Map.Entry<Integer, Integer> entry : new ArrayList<>(rawLosses.entrySet()))
		{
			int lostId = entry.getKey();
			int canonicalId = itemManager.canonicalize(lostId);
			String name = context.getItemName(canonicalId);
			boolean matches = false;
			if (ingredientName.contains("|"))
			{
				for (String opt : ingredientName.split("\\|"))
				{
					if (name.equalsIgnoreCase(opt.trim()))
					{
						matches = true;
						break;
					}
				}
			}
			else
			{
				matches = name.equalsIgnoreCase(ingredientName);
			}

			if (matches)
			{
				int available = entry.getValue();
				int toConsume = Math.min(available, quantityNeeded);
				applyMaterialCost(
					context,
					canonicalId,
					name,
					toConsume,
					availableSessionGains,
					session,
					itemManager
				);

				if (available <= toConsume)
				{
					rawLosses.remove(lostId);
				}
				else
				{
					rawLosses.put(lostId, available - toConsume);
				}
				break;
			}
		}
	}

	private void consumeAccompanyingSecondary(
		ReconciliationContext context,
		Map<Integer, Integer> rawLosses,
		int primaryLostId,
		int quantityNeeded,
		Map<Integer, Integer> availableSessionGains,
		CoinFlowSession session,
		ItemManager itemManager)
	{
		for (Map.Entry<Integer, Integer> entry : new ArrayList<>(rawLosses.entrySet()))
		{
			int lostId = entry.getKey();
			if (lostId == primaryLostId)
			{
				continue;
			}

			int canonicalId = itemManager.canonicalize(lostId);
			String name = context.getItemName(canonicalId);
			String lower = name.toLowerCase(java.util.Locale.ROOT);

			// Exclude tools or empty containers
			if (lower.equals("pestle and mortar") || lower.equals("vial")
				|| lower.equals("empty vial") || lower.equals("vial of water")
				|| context.isIgnored(name))
			{
				continue;
			}

			int available = entry.getValue();
			int toConsume = Math.min(available, quantityNeeded);
			applyMaterialCost(
				context,
				canonicalId,
				name,
				toConsume,
				availableSessionGains,
				session,
				itemManager
			);

			if (available <= toConsume)
			{
				rawLosses.remove(lostId);
			}
			else
			{
				rawLosses.put(lostId, available - toConsume);
			}
			break;
		}
	}

	private void applyMaterialCost(
		ReconciliationContext context,
		int itemId,
		String itemName,
		int quantity,
		Map<Integer, Integer> availableSessionGains,
		CoinFlowSession session,
		ItemManager itemManager)
	{
		int availableInSession = availableSessionGains.getOrDefault(itemId, 0);
		int deductibleQty = Math.min(quantity, availableInSession);
		if (deductibleQty > 0)
		{
			availableSessionGains.put(itemId, availableInSession - deductibleQty);
			CoinFlowSession.TrackedItem gainedItem = session != null ? session.getTrackedItems().get(itemId) : null;
			long priceEach = gainedItem != null ? gainedItem.getPriceEach() : itemManager.getItemPrice(itemId);
			CoinFlowSession.TrackedItem deductItem = new CoinFlowSession.TrackedItem(
				itemId, itemName, deductibleQty, priceEach
			);
			context.addDroppedDeduction(itemId, deductItem);
		}

		int remainingSupplyQty = quantity - deductibleQty;
		if (remainingSupplyQty > 0)
		{
			long price = itemManager.getItemPrice(itemId);
			if (price <= 0)
			{
				if (itemId == ItemID.COINS)
				{
					price = 1;
				}
				else
				{
					ItemComposition comp = itemManager.getItemComposition(itemId);
					if (comp != null)
					{
						price = comp.getHaPrice();
					}
				}
			}
			CoinFlowSession.TrackedItem expenseItem = new CoinFlowSession.TrackedItem(
				itemId, itemName, remainingSupplyQty, price
			);
			context.addSupplyExpense(itemId, expenseItem);

			log.debug("Processing ingredient consumed: {} x{} @ {} gp = {} gp",
				itemName, remainingSupplyQty, price, (long) remainingSupplyQty * price);
		}
	}
}

package com.coinflow.reconciliation;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Stateless semantic pattern matcher for Old School RuneScape production and processing skills.
 * Recognizes transformations in Cooking, Fletching, Herblore, Crafting, Smithing, and Magic.
 */
public final class ProcessingPatternRegistry
{
	private ProcessingPatternRegistry() {}

	public static class MatchResult
	{
		private final int primaryConsumedQty;
		private final Map<String, Integer> secondariesNeeded;
		private final boolean isBurntJunk;
		private final boolean isPotionFinishing;

		public MatchResult(int primaryConsumedQty, Map<String, Integer> secondariesNeeded, boolean isBurntJunk)
		{
			this(primaryConsumedQty, secondariesNeeded, isBurntJunk, false);
		}

		public MatchResult(int primaryConsumedQty, Map<String, Integer> secondariesNeeded, boolean isBurntJunk, boolean isPotionFinishing)
		{
			this.primaryConsumedQty = primaryConsumedQty;
			this.secondariesNeeded = secondariesNeeded != null ? secondariesNeeded : Collections.emptyMap();
			this.isBurntJunk = isBurntJunk;
			this.isPotionFinishing = isPotionFinishing;
		}

		public int getPrimaryConsumedQty()
		{
			return primaryConsumedQty;
		}

		public Map<String, Integer> getSecondariesNeeded()
		{
			return secondariesNeeded;
		}

		public boolean isBurntJunk()
		{
			return isBurntJunk;
		}

		public boolean isPotionFinishing()
		{
			return isPotionFinishing;
		}
	}

	// ── Common Gem Names ──────────────────────────────────────────────────
	private static final Set<String> GEMS = new HashSet<>();
	static
	{
		GEMS.add("sapphire");
		GEMS.add("emerald");
		GEMS.add("ruby");
		GEMS.add("diamond");
		GEMS.add("dragonstone");
		GEMS.add("onyx");
		GEMS.add("zenyte");
		GEMS.add("opal");
		GEMS.add("jade");
		GEMS.add("red topaz");
	}

	// ── Common Metal Names ────────────────────────────────────────────────
	private static final Set<String> METALS = new HashSet<>();
	static
	{
		METALS.add("bronze");
		METALS.add("iron");
		METALS.add("steel");
		METALS.add("silver");
		METALS.add("gold");
		METALS.add("mithril");
		METALS.add("adamantite");
		METALS.add("adamant");
		METALS.add("runite");
