import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;

@RunWith(MockitoJUnitRunner.class)
public class ConsumablesAndDropsHandlerTest
{
	@Mock
	private ItemManager itemManager;

	@Mock
	private CoinFlowConfig config;

	private ConsumablesAndDropsHandler handler;

	@Before
	public void setUp()
	{
		handler = new ConsumablesAndDropsHandler();
		lenient().when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));

		stubItem(ItemID.COINS, "Coins", 1L);
		stubItem(ItemID.PLATINUM, "Platinum token", 1000L);
	}

	private void stubItem(int id, String name, long price)
	{
		ItemComposition comp = mock(ItemComposition.class);
		lenient().when(comp.getName()).thenReturn(name);
		lenient().when(itemManager.getItemComposition(id)).thenReturn(comp);
		lenient().when(itemManager.getItemPrice(id)).thenReturn(price);
	}

	private ReconciliationContext context(Map<Integer, Integer> gains, Map<Integer, Integer> losses)
	{
		return new ReconciliationContext(
			gains,
			losses,
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			null,
			null,
			CoinFlowSession.createNew(),
			itemManager,
			config,
			null
		);
	}

	@Test
	public void coinsOnlyLoss_recordedAsSupplyExpense()
	{
		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 12758);

		ReconciliationContext context = context(new HashMap<>(), losses);
		handler.reconcile(context);

		CoinFlowSession.TrackedItem expense = context.getSupplyExpenses().get(ItemID.COINS);
		Assert.assertNotNull("Coin loss must be recorded as a supply expense", expense);
		Assert.assertEquals(12758, expense.getQuantity());
		Assert.assertEquals(1L, expense.getPriceEach());
	}

	@Test
	public void coinsOnlyLoss_neverEntersDropBookkeeping()
	{
		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 30000);

		ReconciliationContext context = context(new HashMap<>(), losses);
		handler.reconcile(context);

		Assert.assertTrue("Coins must not be tracked as a dropped owned item "
				+ "(would suppress future coin pickups)",
			context.getRecentlyDroppedOwnedItems().isEmpty());
		Assert.assertTrue(context.getRecentlyDroppedItems().isEmpty());
		Assert.assertTrue(context.getDroppedGainsDeductions().isEmpty());
	}

	@Test
	public void platinumLoss_expensedAtFaceValue()
	{
		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.PLATINUM, 5);

		ReconciliationContext context = context(new HashMap<>(), losses);
		handler.reconcile(context);

		CoinFlowSession.TrackedItem expense = context.getSupplyExpenses().get(ItemID.PLATINUM);
		Assert.assertNotNull("Platinum loss must be recorded as a supply expense", expense);
		Assert.assertEquals(5, expense.getQuantity());
		Assert.assertEquals(1000L, expense.getPriceEach());
	}

	@Test
	public void coinLoss_mixedWithConsumable_bothExpensed()
	{
		int sharkId = 385;
		ItemComposition sharkComp = mock(ItemComposition.class);
		lenient().when(sharkComp.getName()).thenReturn("Shark");
		lenient().when(sharkComp.getInventoryActions()).thenReturn(new String[]{"Eat"});
		lenient().when(itemManager.getItemComposition(sharkId)).thenReturn(sharkComp);
		lenient().when(itemManager.getItemPrice(sharkId)).thenReturn(900L);

		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 50000);
		losses.put(sharkId, 1);

		ReconciliationContext context = context(new HashMap<>(), losses);
		handler.reconcile(context);

		Assert.assertNotNull("Coins must be expensed alongside other losses in the same diff",
			context.getSupplyExpenses().get(ItemID.COINS));
		Assert.assertNotNull("Eaten food must still be expensed",
			context.getSupplyExpenses().get(sharkId));
		Assert.assertEquals(50000, context.getSupplyExpenses().get(ItemID.COINS).getQuantity());
	}

	@Test
	public void coinSpend_retiresSessionCoinGains()
	{
		Map<Integer, CoinFlowSession.TrackedItem> loot = new HashMap<>();
		loot.put(ItemID.COINS, new CoinFlowSession.TrackedItem(ItemID.COINS, "Coins", 10000, 1L));
		CoinFlowSession session = CoinFlowSession.createNew()
			.withGainsLossesAndExpenses(loot, new HashMap<>(), new HashMap<>());

		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 4000);
		ReconciliationContext context = new ReconciliationContext(
			new HashMap<>(), losses, new HashMap<>(), new HashMap<>(), new HashMap<>(), new HashMap<>(),
			null, null, session, itemManager, config, null);
		handler.reconcile(context);

		Assert.assertEquals("Spent loot coins must be retired so a later drop cannot deduct them again",
			Long.valueOf(4000), context.getConsumedSessionQuantities().get(ItemID.COINS));
	}

	@Test
	public void platinumToCoinsExchange_nettedToNothing()
	{
		Map<Integer, Integer> gains = new HashMap<>();
		gains.put(ItemID.COINS, 5000);
		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.PLATINUM, 5);

		ReconciliationContext context = context(gains, losses);
		handler.reconcile(context);

		Assert.assertTrue("Exchange must not count as a spend", context.getSupplyExpenses().isEmpty());
		Assert.assertTrue("Exchange must not count as income", context.getRawGains().isEmpty());
	}

	@Test
	public void coinsToPlatinumExchange_nettedLeavesRemainderAsSpend()
	{
		Map<Integer, Integer> gains = new HashMap<>();
		gains.put(ItemID.PLATINUM, 3);
		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 3500);

		ReconciliationContext context = context(gains, losses);
		handler.reconcile(context);

		Assert.assertTrue(context.getRawGains().isEmpty());
		Assert.assertEquals("Only the coins beyond the exchange are a spend",
			500, context.getSupplyExpenses().get(ItemID.COINS).getQuantity());
	}

	@Test
	public void dropIntentCoins_withDropsAsSpentOff_keepsOwnedDropPath()
	{
		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 500);

		ReconciliationContext context = context(new HashMap<>(), losses);
		context.getDropIntentIds().add(ItemID.COINS);
		handler.reconcile(context);

		Assert.assertTrue("An intentional coin drop is not a spend — pickup must stay suppressed",
			context.getSupplyExpenses().isEmpty());
		Assert.assertEquals(Integer.valueOf(500),
			context.getRecentlyDroppedOwnedItems().get(ItemID.COINS));
	}

	@Test
	public void dropIntentCoins_withDropsAsSpentOn_expensedWithReversalBookkeeping()
	{
		lenient().when(config.trackSpent()).thenReturn(true);
		lenient().when(config.countDropsAsSpent()).thenReturn(true);

		Map<Integer, Integer> losses = new HashMap<>();
		losses.put(ItemID.COINS, 500);

		ReconciliationContext context = context(new HashMap<>(), losses);
		context.getDropIntentIds().add(ItemID.COINS);
		handler.reconcile(context);

		CoinFlowSession.TrackedItem expense = context.getSupplyExpenses().get(ItemID.COINS);
		Assert.assertNotNull("Drop-intent coins with drops-as-spent on must be expensed", expense);
		Assert.assertEquals(Integer.valueOf(500),
			context.getRecentlyExpensedDrops().get(ItemID.COINS));
	}
}

package com.coinflow.reconciliation;

import com.coinflow.CoinFlowConfig;
import com.coinflow.CoinFlowSession;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.mock;

@RunWith(MockitoJUnitRunner.class)
public class ItemNotingHandlerTest
{
	@Mock
	private ItemManager itemManager;

	@Mock
	private CoinFlowConfig config;

	private ItemNotingHandler handler;
	private CoinFlowSession session;

	private static final int UNNOTED_RANARR = 257;
	private static final int NOTED_RANARR = 258;

	private static final int UNNOTED_SNAPDRAGON = 3051;
	private static final int NOTED_SNAPDRAGON = 3052;

	private static final int UNNOTED_TEAK_PLANK = 8780;
	private static final int NOTED_TEAK_PLANK = 8781;

	private static final int UNNOTED_DARK_CRAB = 11936;
	private static final int NOTED_DARK_CRAB = 11937;

	@Before
	public void setUp()
	{
		handler = new ItemNotingHandler();
		session = CoinFlowSession.createNew();

		lenient().when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));

		stubNotedPair(UNNOTED_RANARR, NOTED_RANARR, "Grimy ranarr weed", 30_000L);
		stubNotedPair(UNNOTED_SNAPDRAGON, NOTED_SNAPDRAGON, "Grimy snapdragon", 45_000L);
		stubNotedPair(UNNOTED_TEAK_PLANK, NOTED_TEAK_PLANK, "Teak plank", 800L);
		stubNotedPair(UNNOTED_DARK_CRAB, NOTED_DARK_CRAB, "Dark crab", 1_200L);

		// Coins
		stubItem(ItemID.COINS, "Coins", 1L);
		lenient().when(itemManager.canonicalize(ItemID.COINS)).thenReturn(ItemID.COINS);
	}

	private void stubItem(int id, String name, long price)
	{
		ItemComposition comp = mock(ItemComposition.class);
		lenient().when(comp.getName()).thenReturn(name);
		lenient().when(itemManager.getItemComposition(id)).thenReturn(comp);
		lenient().when(itemManager.getItemPrice(id)).thenReturn(price);
	}

	private void stubNotedPair(int unnotedId, int notedId, String name, long price)
	{
		stubItem(unnotedId, name, price);
		stubItem(notedId, name, price);
		lenient().when(itemManager.canonicalize(unnotedId)).thenReturn(unnotedId);
		lenient().when(itemManager.canonicalize(notedId)).thenReturn(unnotedId);
	}

	private ReconciliationContext createContext(Map<Integer, Integer> rawGains, Map<Integer, Integer> rawLosses)
	{
		return new ReconciliationContext(
			rawGains,
			rawLosses,
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			new HashMap<>(),
			null,
			null,
			session,
			itemManager,
			config,
			null,
			new HashMap<>(),
			new HashMap<>()
		);
	}

	@Test
	public void toolLeprechaun_notesHarvestedHerbs_reconcilesSwapWithoutExpenseOrGain()
	{
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_RANARR, 8);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_RANARR, 8);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		Assert.assertTrue("rawLosses should be emptied after 1:1 noting", context.getRawLosses().isEmpty());
		Assert.assertTrue("rawGains should be emptied after 1:1 noting", context.getRawGains().isEmpty());
		Assert.assertTrue("No supply expenses for free leprechaun noting", context.getSupplyExpenses().isEmpty());
	}

	@Test
	public void phials_unnotesPlanksWithFee_reconcilesSwapAndRecordsCoinsExpense()
	{
		// Player unnotes 27 teak planks at Phials (5 coins each = 135 coins)
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(NOTED_TEAK_PLANK, 27);
		rawLosses.put(ItemID.COINS, 135);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(UNNOTED_TEAK_PLANK, 27);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		context.setNotingService(true);
		handler.reconcile(context);

		Assert.assertTrue("rawLosses for planks and exact fee coins should be cleared", context.getRawLosses().isEmpty());
		Assert.assertTrue("rawGains for planks should be cleared", context.getRawGains().isEmpty());

		Assert.assertEquals(1, context.getSupplyExpenses().size());
		CoinFlowSession.TrackedItem feeExpense = context.getSupplyExpenses().get(ItemID.COINS);
		Assert.assertNotNull(feeExpense);
		Assert.assertEquals(135, feeExpense.getQuantity());
		Assert.assertEquals(1L, feeExpense.getPriceEach());
	}

	@Test
	public void piles_notesWildernessResourcesWithFee_reconcilesSwapAndRecordsCoinsExpense()
	{
		// Player notes 20 dark crabs at Piles (5 coins each = 100 coins)
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_DARK_CRAB, 20);
		rawLosses.put(ItemID.COINS, 100);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_DARK_CRAB, 20);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		context.setNotingService(true);
		handler.reconcile(context);

		Assert.assertTrue(context.getRawLosses().isEmpty());
		Assert.assertTrue(context.getRawGains().isEmpty());

		CoinFlowSession.TrackedItem feeExpense = context.getSupplyExpenses().get(ItemID.COINS);
		Assert.assertNotNull(feeExpense);
		Assert.assertEquals(100, feeExpense.getQuantity());
	}

	@Test
	public void partialNoting_leavesRemainderInLosses()
	{
		// Lost 10 unnoted, but only gained 8 noted
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_RANARR, 10);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_RANARR, 8);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		Assert.assertTrue("rawGains should be fully consumed", context.getRawGains().isEmpty());
		Assert.assertEquals(1, context.getRawLosses().size());
		Assert.assertEquals(Integer.valueOf(2), context.getRawLosses().get(UNNOTED_RANARR));
	}

	@Test
	public void multipleItemsNotedSameTick_reconcilesAll()
	{
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_RANARR, 5);
		rawLosses.put(UNNOTED_SNAPDRAGON, 7);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_RANARR, 5);
		rawGains.put(NOTED_SNAPDRAGON, 7);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		Assert.assertTrue(context.getRawLosses().isEmpty());
		Assert.assertTrue(context.getRawGains().isEmpty());
	}

	@Test
	public void excessCoinsLost_onlyDeductsMaxExpectedFee()
	{
		// Unnoted 10 planks (50 gp fee), but player lost 200 coins
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(NOTED_TEAK_PLANK, 10);
		rawLosses.put(ItemID.COINS, 200);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(UNNOTED_TEAK_PLANK, 10);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		context.setNotingService(true);
		handler.reconcile(context);

		Assert.assertTrue(context.getRawGains().isEmpty());
		// 50 gp fee recorded
		CoinFlowSession.TrackedItem feeExpense = context.getSupplyExpenses().get(ItemID.COINS);
		Assert.assertNotNull(feeExpense);
		Assert.assertEquals(50, feeExpense.getQuantity());

		// 150 coins remaining in rawLosses
		Assert.assertEquals(1, context.getRawLosses().size());
		Assert.assertEquals(Integer.valueOf(150), context.getRawLosses().get(ItemID.COINS));
	}

	@Test
	public void coincidentalCoinLoss_withoutNotingServiceIntent_noFeeAttributed()
	{
		// Note swap + unrelated coin loss in the same tick (e.g. free Tool Leprechaun
		// noting while coins left for another reason): the coins must NOT be eaten
		// as a service fee without a noting-service click intent.
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_RANARR, 8);
		rawLosses.put(ItemID.COINS, 40);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_RANARR, 8);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		// The swap is still reconciled...
		Assert.assertTrue(context.getRawGains().isEmpty());
		// ...but the coins remain in rawLosses for other handlers, and no fee is recorded
		Assert.assertEquals(Integer.valueOf(40), context.getRawLosses().get(ItemID.COINS));
		Assert.assertTrue("No fee expense without noting-service intent", context.getSupplyExpenses().isEmpty());
	}

	@Test
	public void differentItems_notMatchedByHandler()
	{
		// Lost ranarr, gained snapdragon
		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_RANARR, 5);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_SNAPDRAGON, 5);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		Assert.assertEquals(1, context.getRawLosses().size());
		Assert.assertEquals(1, context.getRawGains().size());
		Assert.assertTrue(context.getSupplyExpenses().isEmpty());
	}

	@Test
	public void coins_neverTreatedAsNotedItems()
	{
		int fakeCoinsOtherId = 996;
		lenient().when(itemManager.canonicalize(fakeCoinsOtherId)).thenReturn(ItemID.COINS);

		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(ItemID.COINS, 100);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(fakeCoinsOtherId, 100);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		// Coins must not be matched as a noted/unnoted item
		Assert.assertEquals(1, context.getRawLosses().size());
		Assert.assertEquals(1, context.getRawGains().size());
		Assert.assertTrue(context.getSupplyExpenses().isEmpty());
	}

	@Test
	public void splitGains_matchesMultipleGainedEntriesForSingleLost()
	{
		int notedRanarrOtherVariant = 259;
		stubItem(notedRanarrOtherVariant, "Grimy ranarr weed", 30_000L);
		lenient().when(itemManager.canonicalize(notedRanarrOtherVariant)).thenReturn(UNNOTED_RANARR);

		Map<Integer, Integer> rawLosses = new HashMap<>();
		rawLosses.put(UNNOTED_RANARR, 10);

		Map<Integer, Integer> rawGains = new HashMap<>();
		rawGains.put(NOTED_RANARR, 4);
		rawGains.put(notedRanarrOtherVariant, 6);

		ReconciliationContext context = createContext(rawGains, rawLosses);
		handler.reconcile(context);

		Assert.assertTrue(context.getRawLosses().isEmpty());
		Assert.assertTrue(context.getRawGains().isEmpty());
	}
}

package com.coinflow.reconciliation;

import org.junit.Assert;
import org.junit.Test;

public class ProcessingPatternRegistryTest
{
	@Test
	public void cooking_rawFish_matches()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Raw manta ray", "Manta ray", 1);
		Assert.assertNotNull(res);
		Assert.assertEquals(1, res.getPrimaryConsumedQty());
		Assert.assertFalse(res.isBurntJunk());
	}

	@Test
	public void cooking_burntFish_markedAsBurntJunk()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Raw shark", "Burnt shark", 1);
		Assert.assertNotNull(res);
		Assert.assertEquals(1, res.getPrimaryConsumedQty());
		Assert.assertTrue(res.isBurntJunk());
	}

	@Test
	public void cooking_unrelatedBurntItems_doesNotMatchBurntJunk()
	{
		Assert.assertNull(ProcessingPatternRegistry.match("Raw shark", "Burnt page", 1));
		Assert.assertNull(ProcessingPatternRegistry.match("Raw manta ray", "Burnt page", 1));
	}

	@Test
	public void fletching_logsToBows_matches1to1()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Magic logs", "Magic longbow (u)", 1);
		Assert.assertNotNull(res);
		Assert.assertEquals(1, res.getPrimaryConsumedQty());

		ProcessingPatternRegistry.MatchResult res2 =
			ProcessingPatternRegistry.match("Logs", "Shortbow (u)", 1);
		Assert.assertNotNull(res2);
		Assert.assertEquals(1, res2.getPrimaryConsumedQty());
	}

	@Test
	public void fletching_logsToShield_requires2LogsPerShield()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Magic logs", "Magic shield", 2);
		Assert.assertNotNull(res);
		Assert.assertEquals(4, res.getPrimaryConsumedQty());
	}

	@Test
	public void fletching_logsToShafts_correctRatios()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Logs", "Arrow shaft", 15);
		Assert.assertNotNull(res);
		Assert.assertEquals(1, res.getPrimaryConsumedQty());

		ProcessingPatternRegistry.MatchResult resRedwood =
			ProcessingPatternRegistry.match("Redwood logs", "Arrow shaft", 60);
		Assert.assertNotNull(resRedwood);
		Assert.assertEquals(1, resRedwood.getPrimaryConsumedQty());
	}

	@Test
	public void fletching_bowStringing_requiresBowString()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Magic longbow (u)", "Magic longbow", 1);
		Assert.assertNotNull(res);
		Assert.assertEquals(1, res.getPrimaryConsumedQty());
		Assert.assertEquals(Integer.valueOf(1), res.getSecondariesNeeded().get("bow string"));
	}

	@Test
	public void herblore_cleaningHerbs_matches()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Grimy ranarr weed", "Ranarr weed", 14);
		Assert.assertNotNull(res);
		Assert.assertEquals(14, res.getPrimaryConsumedQty());
	}

	@Test
	public void herblore_unfinishedPotions_requiresVialOfWater()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Ranarr weed", "Ranarr potion (unf)", 14);
		Assert.assertNotNull(res);
		Assert.assertEquals(14, res.getPrimaryConsumedQty());
		Assert.assertEquals(Integer.valueOf(14), res.getSecondariesNeeded().get("vial of water"));
	}

	@Test
	public void crafting_cutGems_matches()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Uncut diamond", "Diamond", 5);
		Assert.assertNotNull(res);
		Assert.assertEquals(5, res.getPrimaryConsumedQty());
	}

	@Test
	public void crafting_jewellery_requiresBarAndGem()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Gold bar", "Ruby ring", 1);
		Assert.assertNotNull(res);
		Assert.assertEquals(1, res.getPrimaryConsumedQty());
		Assert.assertEquals(Integer.valueOf(1), res.getSecondariesNeeded().get("ruby"));
	}

	@Test
	public void crafting_dragonhideArmor_requiresMultipleLeathers()
	{
		ProcessingPatternRegistry.MatchResult resBody =
			ProcessingPatternRegistry.match("Green dragon leather", "Green d'hide body", 1);
		Assert.assertNotNull(resBody);
		Assert.assertEquals(3, resBody.getPrimaryConsumedQty());

		ProcessingPatternRegistry.MatchResult resChaps =
			ProcessingPatternRegistry.match("Green dragon leather", "Green d'hide chaps", 2);
		Assert.assertNotNull(resChaps);
		Assert.assertEquals(4, resChaps.getPrimaryConsumedQty());
	}

	@Test
	public void smithing_smelting_requiresOreAndCoal()
	{
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Mithril ore", "Mithril bar", 5);
		Assert.assertNotNull(res);
		Assert.assertEquals(5, res.getPrimaryConsumedQty());
		Assert.assertEquals(Integer.valueOf(20), res.getSecondariesNeeded().get("coal"));
	}

	@Test
	public void smithing_forgingPlatebody_requires5Bars()
	{
		// Real OSRS item names: Runite bar -> Rune platebody
		ProcessingPatternRegistry.MatchResult res =
			ProcessingPatternRegistry.match("Runite bar", "Rune platebody", 2);
		Assert.assertNotNull(res);
		Assert.assertEquals(10, res.getPrimaryConsumedQty());

		// Adamantite bar -> Adamant platebody
		ProcessingPatternRegistry.MatchResult resAddy =
			ProcessingPatternRegistry.match("Adamantite bar", "Adamant platebody", 1);
